// Generated by scripts/build-print-station.mjs — do not edit by hand.
//
// The Print Station's own source, compiled in so the partner download route
// can zip it. A serverless function does not carry public/ on its disk, so
// reading the files at request time would work locally and 500 in production.
//
// print-station/distribution.test.mjs fails if this drifts from the source.

export const PRINT_STATION_FILES: Record<string, string> = {
  "station.mjs": "#!/usr/bin/env node\nimport { createServer } from \"node:http\";\nimport { execFile } from \"node:child_process\";\nimport { mkdtempSync, writeFileSync, rmSync } from \"node:fs\";\nimport { tmpdir } from \"node:os\";\nimport { dirname, join } from \"node:path\";\nimport { fileURLToPath } from \"node:url\";\n\nimport { adoptedBundledKey, configPath, configProblems, isReady, loadConfig, redactConfig, saveConfig } from \"./lib/config.mjs\";\nimport { isAllowedHost, isAllowedWrite, tokenFromForm } from \"./lib/local-guard.mjs\";\nimport { secureBundledKey } from \"./lib/secure-key.mjs\";\nimport { applyUpdate, RESTART_CODE } from \"./lib/self-update.mjs\";\nimport { createApi } from \"./lib/api.mjs\";\nimport { createLog } from \"./lib/log.mjs\";\nimport { choosePrinter, createWorker, diagnose } from \"./lib/worker.mjs\";\nimport { defaultPrinter, ensurePrintHelper, listPrinters, pickStartupPrinter, printFile } from \"./lib/printer.mjs\";\nimport { renderPage } from \"./lib/page.mjs\";\nimport { PRINT_STATION_VERSION } from \"./lib/version.mjs\";\n\n/**\n * DigiConnect Print Station.\n *\n * A shop owner double-clicks this, a page opens on their own computer, they\n * paste the key from their dashboard and pick a printer. From then on the\n * computer prints what customers order at the QR taped to the counter, and\n * deletes their files the moment the pages are out.\n *\n * It listens on localhost only. Nothing on the shop's network — let alone the\n * internet — can reach this program: it makes outbound calls to the website\n * and answers nobody.\n */\n\nconst PORT = Number(process.env.DCPS_PORT || 7171);\n\nconst log = createLog();\nconst state = {\n  running: false,\n  connected: false,\n  queued: 0,\n  printed: 0,\n  failed: 0,\n  lastError: null,\n  lastPollAt: null,\n  stoppedReason: null,\n  stationName: null,\n  // Printers the partner chose in the website panel, read on every poll.\n  serverPrinter: null,\n  serverColorPrinter: null,\n};\n\nlet config = loadConfig();\nlet printers = [];\nlet worker = null;\n\n/* ─────────────────────────────────────────────────────────────────────────\n   Updating itself\n   ───────────────────────────────────────────────────────────────────────── */\n\nconst PROGRAM_FOLDER = dirname(fileURLToPath(import.meta.url));\nlet updating = false;\n\n/**\n * Download the current program and restart into it. The key and settings\n * live in the user profile, not in this folder, so nothing is lost.\n */\nasync function installUpdate(latest) {\n  if (updating) return;\n  updating = true;\n  try {\n    log.push(\"info\", `Naya version v${latest} install ho raha hai...`);\n    const api = createApi({ serverUrl: config.serverUrl, agentToken: config.agentToken });\n    const { files, version } = await api.fetchUpdate();\n    const written = applyUpdate({ files, folder: PROGRAM_FOLDER });\n    log.push(\"success\", `v${version} install ho gaya (${written} files). Restart ho raha hai...`);\n    stopWorker();\n    // The keepalive (or the launcher's loop) starts the new version.\n    setTimeout(() => process.exit(RESTART_CODE), 500);\n  } catch (error) {\n    updating = false;\n    log.push(\"error\", `Update nahi ho paya: ${error instanceof Error ? error.message : String(error)}`);\n  }\n}\n\n/* ─────────────────────────────────────────────────────────────────────────\n   The loop\n   ───────────────────────────────────────────────────────────────────────── */\n\nfunction stopWorker() {\n  worker?.stop();\n  worker = null;\n  state.running = false;\n  state.connected = false;\n}\n\nfunction startWorker() {\n  stopWorker();\n\n  const problems = configProblems(config);\n  if (problems.length) {\n    state.stoppedReason = problems[0];\n    return;\n  }\n\n  state.stoppedReason = null;\n  const api = createApi({ serverUrl: config.serverUrl, agentToken: config.agentToken });\n\n  worker = createWorker({\n    api,\n    config,\n    getPrinters: () => printers,\n    currentVersion: PRINT_STATION_VERSION,\n    onUpdateRequested: (latest) => installUpdate(latest),\n    state,\n    log: log.push,\n    print: ({ filePath, job }) => {\n      const printerName = choosePrinter({\n        job,\n        serverPrinter: state.serverPrinter,\n        serverColorPrinter: state.serverColorPrinter,\n        printers,\n        fallback: config.printerName,\n      });\n      return printFile({ filePath, printerName, job, config });\n    },\n  });\n\n  worker.start();\n  state.running = true;\n  log.push(\"info\", `Watching for jobs. Printing to \"${config.printerName}\".`);\n}\n\n/* ─────────────────────────────────────────────────────────────────────────\n   The test page\n   ───────────────────────────────────────────────────────────────────────── */\n\n/**\n * A one-page PDF, built by hand.\n *\n * Written as bytes rather than pulled from a library because this program has\n * no dependencies on purpose — a shop owner should be able to run it on a\n * counter PC with nothing installed but Node. It exists so a partner can\n * prove the printer works before a customer is standing there.\n */\nfunction testPagePdf() {\n  const text = `DigiConnect Print Station works. ${new Date().toLocaleString()}`;\n  const content = `BT /F1 16 Tf 60 700 Td (${text.replace(/[()\\\\]/g, \"\")}) Tj ET`;\n  const objects = [\n    \"<< /Type /Catalog /Pages 2 0 R >>\",\n    \"<< /Type /Pages /Kids [3 0 R] /Count 1 >>\",\n    \"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>\",\n    `<< /Length ${content.length} >>\\nstream\\n${content}\\nendstream`,\n    \"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>\",\n  ];\n\n  let pdf = \"%PDF-1.4\\n\";\n  const offsets = [];\n  objects.forEach((object, index) => {\n    offsets.push(pdf.length);\n    pdf += `${index + 1} 0 obj\\n${object}\\nendobj\\n`;\n  });\n\n  const xref = pdf.length;\n  pdf += `xref\\n0 ${objects.length + 1}\\n0000000000 65535 f \\n`;\n  for (const offset of offsets) pdf += `${String(offset).padStart(10, \"0\")} 00000 n \\n`;\n  pdf += `trailer\\n<< /Size ${objects.length + 1} /Root 1 0 R >>\\nstartxref\\n${xref}\\n%%EOF\\n`;\n\n  return Buffer.from(pdf, \"latin1\");\n}\n\nasync function printTestPage() {\n  if (!config.printerName) throw new Error(\"Choose a printer first.\");\n\n  const folder = mkdtempSync(join(tmpdir(), \"dcps-test-\"));\n  const path = join(folder, \"test.pdf\");\n  writeFileSync(path, testPagePdf());\n  try {\n    await printFile({\n      filePath: path,\n      printerName: config.printerName,\n      job: { copies: 1, pages: 1, paper_size: \"A4\", color_mode: \"mono\" },\n      config,\n    });\n  } finally {\n    rmSync(folder, { recursive: true, force: true });\n  }\n}\n\n/* ─────────────────────────────────────────────────────────────────────────\n   The local screen\n   ───────────────────────────────────────────────────────────────────────── */\n\nfunction json(response, status, body) {\n  const payload = JSON.stringify(body);\n  response.writeHead(status, {\n    \"Content-Type\": \"application/json\",\n    \"Content-Length\": Buffer.byteLength(payload),\n    \"Cache-Control\": \"no-store\",\n  });\n  response.end(payload);\n}\n\nasync function readBody(request) {\n  const chunks = [];\n  for await (const chunk of request) {\n    chunks.push(chunk);\n    // A setup form is a few hundred bytes. Anything larger is not a form.\n    if (chunks.reduce((total, part) => total + part.length, 0) > 64 * 1024) break;\n  }\n  try {\n    return JSON.parse(Buffer.concat(chunks).toString(\"utf8\") || \"{}\");\n  } catch {\n    return {};\n  }\n}\n\nconst server = createServer(async (request, response) => {\n  const url = new URL(request.url, \"http://localhost\");\n\n  // See lib/local-guard.mjs: no other website may read or change this page.\n  if (!isAllowedHost(request.headers.host, PORT)) {\n    json(response, 403, { error: \"Forbidden\" });\n    return;\n  }\n  if (\n    !isAllowedWrite({\n      method: request.method,\n      origin: request.headers.origin,\n      contentType: request.headers[\"content-type\"],\n      port: PORT,\n    })\n  ) {\n    json(response, 403, { error: \"Forbidden\" });\n    return;\n  }\n\n  if (url.pathname === \"/\" && request.method === \"GET\") {\n    const page = renderPage();\n    response.writeHead(200, { \"Content-Type\": \"text/html; charset=utf-8\", \"Cache-Control\": \"no-store\" });\n    response.end(page);\n    return;\n  }\n\n  if (url.pathname === \"/api/state\" && request.method === \"GET\") {\n    json(response, 200, {\n      ...state,\n      // The key is never sent back, even to this page: shown masked.\n      config: redactConfig(config),\n      printers,\n      version: PRINT_STATION_VERSION,\n      problems: configProblems(config),\n      configPath: configPath(),\n      log: log.lines(),\n    });\n    return;\n  }\n\n  if (url.pathname === \"/api/save\" && request.method === \"POST\") {\n    const body = await readBody(request);\n    // The token field is left untouched when the form sends back nothing —\n    // a partner editing the poll interval should not have to fetch their key\n    // out of a drawer.\n    config = saveConfig({ ...config, ...body, agentToken: tokenFromForm(body.agentToken, config.agentToken) });\n    printers = await listPrinters();\n    log.push(\"info\", \"Settings saved.\");\n    startWorker();\n    json(response, 200, { ok: isReady(config), problems: configProblems(config) });\n    return;\n  }\n\n  if (url.pathname === \"/api/update\" && request.method === \"POST\") {\n    if (!state.updateAvailable || !state.latestVersion) {\n      json(response, 200, { ok: false, error: \"Aap pehle se latest version par hain.\" });\n      return;\n    }\n    void installUpdate(state.latestVersion);\n    json(response, 200, { ok: true });\n    return;\n  }\n\n  if (url.pathname === \"/api/check\" && request.method === \"POST\") {\n    /*\n      The button that ends the guessing.\n\n      It asks the website who this key belongs to and reports the answer in\n      words, rather than leaving the shop to infer it from a status code that\n      means four different things.\n    */\n    const api = createApi({ serverUrl: config.serverUrl, agentToken: config.agentToken });\n    const findings = await diagnose({ api, config, printers });\n    for (const finding of findings) {\n      if (finding.level === \"error\") log.push(\"error\", finding.text);\n      else if (finding.level === \"fix\") log.push(\"warn\", finding.text);\n    }\n    json(response, 200, { findings });\n    return;\n  }\n\n  if (url.pathname === \"/api/test-print\" && request.method === \"POST\") {\n    try {\n      await printTestPage();\n      log.push(\"success\", `Test page sent to \"${config.printerName}\".`);\n      json(response, 200, { ok: true, printer: config.printerName });\n    } catch (error) {\n      const message = error instanceof Error ? error.message : String(error);\n      log.push(\"error\", `Test page failed: ${message}`);\n      json(response, 200, { ok: false, error: message });\n    }\n    return;\n  }\n\n  json(response, 404, { error: \"Not found\" });\n});\n\n/** Open the shop owner's browser at the setup page, on whichever OS this is. */\nfunction openBrowser(url) {\n  const command =\n    process.platform === \"win32\" ? [\"cmd\", [\"/c\", \"start\", \"\", url]]\n    : process.platform === \"darwin\" ? [\"open\", [url]]\n    : [\"xdg-open\", [url]];\n  execFile(command[0], command[1], { windowsHide: true }, () => {\n    /* No browser is not a failure — the address is printed below. */\n  });\n}\n\n/*\n  Bound to 127.0.0.1 rather than every interface.\n\n  This program holds the key to a shop's print queue and, briefly, its\n  customers' documents. On a shop's flat network — often shared with a\n  neighbour's wifi — a server listening on 0.0.0.0 would let anybody on it\n  read the settings page and change the printer.\n*/\nserver.listen(PORT, \"127.0.0.1\", async () => {\n  console.log(\"\");\n  console.log(`  DigiConnect Print Station  v${PRINT_STATION_VERSION}`);\n  console.log(`  Settings: http://localhost:${PORT}`);\n  console.log(`  Config file: ${configPath()}`);\n  console.log(\"\");\n\n  // First line in the log, so a screenshot always says which build this is.\n  log.push(\"info\", `DigiConnect Print Station v${PRINT_STATION_VERSION}`);\n\n  if (adoptedBundledKey(config)) {\n    log.push(\"info\", \"Key taken from this downloaded folder.\");\n  }\n\n  /*\n    Retire the zip's key before printing anything with it. Retried every\n    minute while the internet is down; printing does not wait for it — the\n    old key keeps working until the swap succeeds.\n  */\n  const secure = async () => {\n    try {\n      const before = config.agentToken;\n      config = await secureBundledKey({\n        config,\n        save: saveConfig,\n        makeApi: (agentToken) => createApi({ serverUrl: config.serverUrl, agentToken }),\n        log: log.push,\n      });\n      if (config.agentToken !== before) startWorker();\n      return true;\n    } catch {\n      return false;\n    }\n  };\n  if (!(await secure())) {\n    const retry = setInterval(async () => {\n      if (await secure()) clearInterval(retry);\n    }, 60_000);\n    retry.unref();\n  }\n\n  printers = await listPrinters();\n  if (!printers.length) log.push(\"warn\", \"No printer found on this computer yet.\");\n\n  /*\n    No printer chosen yet: start with the one this computer already prints\n    to. A shop that installed and walked away is printing, not stuck on a\n    setup page — and the partner can change it from the website panel.\n  */\n  if (!config.printerName && printers.length) {\n    const chosen = pickStartupPrinter(printers, await defaultPrinter());\n    if (chosen) {\n      config = saveConfig({ ...config, printerName: chosen });\n      log.push(\"info\", `Printer chosen automatically: \"${chosen}\". Change it any time from your partner panel.`);\n    }\n  }\n\n  // A printer plugged in later shows up in the panel without a restart.\n  setInterval(() => {\n    listPrinters()\n      .then((found) => {\n        if (found.length) printers = found;\n      })\n      .catch(() => {});\n  }, 5 * 60_000).unref();\n\n  // Best effort, and never blocking: photos print without it either way.\n  await ensurePrintHelper({ serverUrl: config.serverUrl, config, log: log.push });\n\n  startWorker();\n  if (!isReady(config)) openBrowser(`http://localhost:${PORT}`);\n});\n\nserver.on(\"error\", (error) => {\n  if (error.code === \"EADDRINUSE\") {\n    console.error(`\\n  Print Station is already running. Open http://localhost:${PORT}\\n`);\n    openBrowser(`http://localhost:${PORT}`);\n    process.exit(0);\n  }\n  console.error(error);\n  process.exit(1);\n});\n\nfor (const signal of [\"SIGINT\", \"SIGTERM\"]) {\n  process.on(signal, () => {\n    stopWorker();\n    server.close(() => process.exit(0));\n  });\n}\n",
  "README.md": "# DigiConnect Print Station\n\nThe program that actually prints.\n\nA customer scans the QR taped to your counter, chooses A4 or A3, black or\ncolour, uploads their file and pays. This program — running on the computer\nyour printer is plugged into — collects that job, prints it, and deletes the\nfile. Nobody in the shop opens the customer's document, and nothing of theirs\nis left on the computer afterwards.\n\n---\n\n## Install it (Windows)\n\n**The easy way.** In your partner dashboard, open **Print counter** and press\n**Print Station download kijiye**. You get a zip with your key already inside —\nnothing to paste.\n\n1. Extract the zip. Do not run it from inside the zip.\n2. Double-click **Start Print Station** — once. That is the whole install.\n\nThat one double-click:\n\n- fetches Node.js if the computer has none (no installer, no admin password),\n- copies the program to `%LOCALAPPDATA%\\DigiConnectPrintStation\\app`, so the\n  Downloads folder can be deleted afterwards,\n- adds it to Windows startup and starts it with no window,\n- runs it under a keepalive that restarts it if it ever crashes,\n- picks the computer's default printer (skipping \"Print to PDF\"-style ones).\n\nThe printer — and an optional separate printer for colour jobs — is then\nchosen from the partner panel (**Print counter → Printer**). The program\nreports its printers to the website, so nothing has to be done on the PC.\n\nTo update, download again and run **Start Print Station** from the new\nfolder: it installs over the old copy.\n\nEvery download issues a new key and retires the old one, so keep one folder on\none computer.\n\n**The other way**, if the download is blocked. Open **PowerShell** and paste:\n\n```powershell\nirm https://www.rnos.in/print-station/install.ps1 | iex\n```\n\nThen copy your key from the dashboard into the settings page yourself. If\nPowerShell refuses to run it, run `Set-ExecutionPolicy -Scope Process -Bypass`\nfirst.\n\n### Node.js, without installing Node.js\n\nThe program is written for Node, and pointing a shop at nodejs.org was where\ninstalls died: an MSI that wants administrator rights the counter assistant\ndoes not have, on a page with half a dozen buttons.\n\nSo it fetches Node itself, the first time it is run:\n\n- The official Windows **ZIP** from nodejs.org — one self-contained\n  `node.exe`. No installer, no administrator rights, nothing added to PATH.\n- The newest LTS, asked for by reading `nodejs.org/dist/index.json` rather\n  than a version number hardcoded here that would one day 404 on a counter PC.\n- Checked against the published `SHASUMS256.txt` before it is ever run.\n- Kept in `%LOCALAPPDATA%\\DigiConnectPrintStation\\node`, so it is fetched\n  once and reused by every later download of the Print Station.\n\nA Node already installed the normal way wins — the fetch does not happen at\nall, and nothing on the machine is touched.\n\nIf the download fails it is nearly always the shop's own network. Opening\n[nodejs.org](https://nodejs.org/en/download) in a browser on that computer\ntells you which side the block is on.\n\n### Printing helper\n\nThe program fetches a small helper on first run, by itself. You do not install\nanything. If it cannot be fetched, printing falls back to Windows' own PDF\nviewer — still correct on copies, paper size and colour, just slower, one copy\nat a time.\n\n## Install it (macOS or Linux)\n\nDownload the folder, then:\n\n```sh\n./start-print-station.sh\n```\n\nPrinting goes through CUPS (`lp`), which is already there. Nothing else to\ninstall.\n\n---\n\n## Set it up\n\nThe program opens a page on your own computer at **http://localhost:7171**.\n\n1. **Your key** — copy it from your partner dashboard under **Print counter**.\n   It starts with `dcp_` and is shown only once. If you have lost it, issue a\n   new one from the same screen; the old one stops working immediately.\n2. **Printer** — pick the printer from the list. The list is what Windows or\n   macOS itself reports, so if the printer is missing here it is missing from\n   the computer too.\n3. **Print a test page** — do this before your first customer. A page comes\n   out of the tray, and you know the whole chain works.\n\nIf you used the download, steps 1 and 2 are already done for you.\n\n---\n\n## Run it without the black window\n\nThe console window is not the program's home, only its front door. Nobody at a\ncounter should have to guard it, and one accidental X at closing time means the\nnext customer pays for pages that never come out.\n\n**Start Print Station** does this by itself now. **Background me chalaiye**\ndoes the same thing on its own, for a copy that was set up before v2.0.\nFrom then on:\n\n- The program runs with no window at all.\n- It starts by itself every time the computer is switched on.\n- Its state is at **http://localhost:7171**, same as before.\n\nTo go back to the old way, double-click **Background band kijiye** — that stops\nthe hidden copy and removes it from Windows startup.\n\nIt needs no administrator rights: it writes one shortcut into your own Startup\nfolder (`shell:startup`), which is why it works on a shop machine whose owner\nis not an admin. The hidden start uses `wscript`; on a Windows with VBScript\nremoved it falls back to PowerShell.\n\nThe hidden copy runs under `lib/keepalive-station.mjs`, which starts the\nprogram again if it ever crashes (2s, then backing off to a minute between\nattempts). If printing still stops with the computer on, open\nhttp://localhost:7171 — if that page does not load, run **Start Print\nStation** again.\n\n---\n\n## What the screen tells you\n\n| It says | It means |\n| --- | --- |\n| **Connected** | Talking to the website. Jobs will print. |\n| **Trying to reach the website…** | Your internet is down. Jobs are safe and will print when it returns. |\n| **Stopped** | Something needs you — the message underneath says what. |\n| **Waiting** | Jobs paid for and not yet printed. |\n\n---\n\n## When something goes wrong\n\n**\"Your key was refused.\"**\nThe key is wrong or has been replaced — most often because a newer download\nretired it. Download the bundle again, or issue a new key from the dashboard.\n\n**\"The server cannot reach its database right now.\"**\nNot your key, and nothing to re-paste. The site is having trouble; the program\nkeeps retrying and will pick up where it left off.\n\n**\"No internet.\"**\nNothing is lost. The jobs stay on the server and print the moment the\nconnection is back.\n\n**\"The printer did not accept the job.\"**\nPaper, power, or an error light on the printer itself. Fix it, then use\n**Print a test page** to confirm before the next customer.\n\n**Nothing prints and the screen says Connected.**\nThe job is queueing against a different counter. Check the key belongs to this\nshop — the shop's name appears next to the Connected light once it has spoken\nto the website.\n\n---\n\n## What this program does with a customer's file\n\n- Downloads it to a temporary folder only when it is about to print.\n- Deletes it as soon as the print command returns — including when printing\n  failed.\n- Never writes a customer's file name or contents to a log file.\n- Listens on `127.0.0.1` only, so nothing else on the shop's network — or the\n  internet — can reach it.\n- Stores your key in your own user profile, readable only by you.\n\nThe counter is at\n`%LOCALAPPDATA%\\DigiConnectPrintStation\\config.json` on Windows and\n`~/.config/digiconnect-print-station/config.json` elsewhere. Deleting it\nresets the setup.\n\n---\n\n## For developers\n\nSource of truth is `print-station/` in the repository. `public/print-station/`\nis a copy for downloading, rebuilt with:\n\n```sh\nnode scripts/build-print-station.mjs\n```\n\n`print-station/distribution.test.mjs` fails if the two drift apart. The rest\nof the tests run with the main suite (`npm test`).\n",
  "Start Print Station.bat": "@echo off\ntitle DigiConnect Print Station\ncd /d \"%~dp0\"\n\nREM  The shop owner double-clicks this file. Nothing else.\nREM\nREM  Ye file akeli kaam nahi karti.\nREM\nREM  A shop opened the zip in Explorer, dragged this one file onto the\nREM  Desktop, and ran it. Node then looked for station.mjs next to it, found\nREM  nothing, and printed a module-not-found stack trace with a path in it --\nREM  which reads like the program is broken rather than in the wrong place.\nREM  It printed fine the day before, from inside the extracted folder.\n\nif not exist \"%~dp0station.mjs\" goto :nofolder\n\nREM  Node is the only thing this program needs, and a counter PC usually does\nREM  not have it. Sending the shop to nodejs.org was where installs died: an\nREM  MSI that wants admin rights, on a page with six buttons. This fetches it\nREM  instead -- once, into our own folder, no installer, no admin.\n\ncall powershell -NoProfile -ExecutionPolicy Bypass -File \"%~dp0lib\\ensure-node.ps1\"\n\nset \"DCPS_NODE_FILE=%LOCALAPPDATA%\\DigiConnectPrintStation\\node-path.txt\"\nif not exist \"%DCPS_NODE_FILE%\" goto :nonode\nset \"NODE=\"\nset /p NODE=<\"%DCPS_NODE_FILE%\"\nif not defined NODE goto :nonode\nif not exist \"%NODE%\" goto :nonode\n\nREM  One double-click, installed for good.\nREM\nREM  Shops ran this, saw it print, and never found the second file that\nREM  makes it survive a reboot -- so the next morning nothing printed. Now\nREM  this file does both: it installs the program into the user's own\nREM  AppData, adds it to Windows startup, and starts it hidden with a\nREM  keepalive that restarts it if it ever crashes. No admin rights.\nREM  If that fails for any reason, it falls back to running right here.\n\nif /i \"%DCPS_FOREGROUND%\"==\"1\" goto :foreground\n\necho.\necho   DigiConnect Print Station install ho raha hai (sirf ek baar)...\necho.\npowershell -NoProfile -ExecutionPolicy Bypass -File \"%~dp0lib\\background.ps1\"\nif errorlevel 1 goto :foreground\n\nstart \"\" \"http://localhost:7171\"\necho.\necho   Ho gaya. Ye window band kar sakte hain - printing chalti rahegi.\necho.\npause\nexit /b 0\n\n:foreground\necho.\necho   Starting DigiConnect Print Station...\necho   Leave this window open.\necho.\n\n:run\n\"%NODE%\" \"%~dp0station.mjs\"\nREM  75 means \"updated itself, start me again\".\nif errorlevel 75 if not errorlevel 76 goto :run\n\nREM  If the program stops, the window stays so the reason can be read.\necho.\necho   Print Station has stopped.\npause\nexit /b 0\n\n:nonode\necho.\necho   Node.js taiyar nahi ho paya, isliye program shuru nahi kar sakta.\necho   Uparwala message padhiye - usme wajah likhi hai.\necho.\npause\nexit /b 1\n\n:nofolder\necho.\necho   Ye file akele nahi chalti.\necho.\necho   Lagta hai \"Start Print Station\" ko zip se nikal kar alag rakh diya gaya\necho   hai. Iske saath station.mjs aur lib folder bhi hone chahiye.\necho.\necho   Kya kariye:\necho     1. Downloads me DigiConnect-Print-Station...zip par right-click\necho     2. \"Extract All\" -^> Extract\necho     3. Jo folder bane, uske ANDAR jaiye\necho     4. Wahin se \"Start Print Station\" par double-click\necho.\necho   Abhi ye yahan se chalane ki koshish hui:\necho   %~dp0\necho.\npause\nexit /b 1\n",
  "Background me chalaiye.bat": "@echo off\ntitle DigiConnect Print Station - background me chalaiye\ncd /d \"%~dp0\"\n\nREM  Double-click this once, and the black window is never needed again.\nREM\nREM  The program keeps running with no window, and starts by itself every\nREM  time the computer is switched on. Undo it with \"Background band kijiye\".\n\nif not exist \"%~dp0station.mjs\" goto :nofolder\n\npowershell -NoProfile -ExecutionPolicy Bypass -File \"%~dp0lib\\background.ps1\"\npause\nexit /b 0\n\n:nofolder\necho.\necho   Ye file akele nahi chalti.\necho.\necho   Poori zip ko \"Extract All\" kijiye, aur jo folder bane uske ANDAR se\necho   ye file chalaiye - station.mjs aur lib isi ke saath hone chahiye.\necho.\necho   Abhi ye yahan se chalane ki koshish hui:\necho   %~dp0\necho.\npause\nexit /b 1\n",
  "Background band kijiye.bat": "@echo off\ntitle DigiConnect Print Station - background band kijiye\ncd /d \"%~dp0\"\n\nREM  Stops the hidden copy and takes it out of Windows startup. Printing then\nREM  happens only while \"Start Print Station\" is open, as it did before.\n\nif not exist \"%~dp0station.mjs\" goto :nofolder\n\npowershell -NoProfile -ExecutionPolicy Bypass -File \"%~dp0lib\\background.ps1\" -Remove\npause\nexit /b 0\n\n:nofolder\necho.\necho   Ye file akele nahi chalti. Poori zip Extract kijiye aur folder ke\necho   ANDAR se chalaiye.\necho.\npause\nexit /b 1\n",
  "start-print-station.sh": "#!/bin/sh\n# The same thing for a shop running macOS or Linux.\ncd \"$(dirname \"$0\")\" || exit 1\n\n# Same trap as on Windows: this file copied out of the folder on its own,\n# with station.mjs left behind.\nif [ ! -f ./station.mjs ]; then\n  echo \"\"\n  echo \"  This file cannot run on its own.\"\n  echo \"  Extract the whole zip and run it from inside that folder,\"\n  echo \"  next to station.mjs and lib/.\"\n  echo \"\"\n  exit 1\nfi\n\nif ! command -v node >/dev/null 2>&1; then\n  echo \"\"\n  echo \"  DigiConnect Print Station needs Node.js.\"\n  echo \"  Install it from https://nodejs.org/en/download and run this again.\"\n  echo \"\"\n  exit 1\nfi\n\nexec node ./station.mjs\n",
  "lib/config.mjs": "import { mkdirSync, readFileSync, writeFileSync, existsSync } from \"node:fs\";\nimport { homedir, platform } from \"node:os\";\nimport { dirname, join } from \"node:path\";\nimport { fileURLToPath } from \"node:url\";\n\n/**\n * What this computer remembers between restarts.\n *\n * A shop owner sets this up once. The file lives in the operating system's\n * own per-user config location rather than beside the program, so that\n * replacing the program folder — a re-download, an update — does not lose the\n * key and force a trip back to the website.\n */\n\nexport const DEFAULTS = {\n  /*\n    Where the counter lives.\n\n    The www is not decoration. The bare domain answers with a redirect to\n    this one, and a redirect across origins costs the Authorization header —\n    so every key sent to the bare domain arrived with no key at all, and the\n    server truthfully said it was refused. Overridable, so a test install can\n    point elsewhere.\n  */\n  serverUrl: \"https://www.rnos.in\",\n  /** The key issued at /ap/print. Shown once, so it is stored here. */\n  agentToken: \"\",\n  /** The printer's name as the operating system spells it. */\n  printerName: \"\",\n  /**\n   * How often to ask for work.\n   *\n   * Five seconds: a customer is standing at the counter watching, so a minute\n   * feels broken, and anything under a second is a shop hammering a server\n   * all day for nothing.\n   */\n  pollSeconds: 5,\n  /** Print in colour only when the job asked for it. */\n  duplex: false,\n  /** Path to SumatraPDF, if the shop uses it. Found automatically when blank. */\n  sumatraPath: \"\",\n  /*\n    The download key this computer has already taken.\n\n    Not a setting anybody edits — it is how the program tells \"the folder I\n    was started from carries a newer key\" from \"the shop typed its own key\n    in\". Without it a bundle's key would either be ignored forever, or\n    clobber a hand-entered one on every restart.\n  */\n  seededFrom: \"\",\n  /*\n    A key this computer made for itself and is swapping in for the one that\n    came in the zip (see secure-key.mjs). Saved before the server is asked,\n    so a reply lost on the way back cannot lock the shop out.\n  */\n  pendingToken: \"\",\n};\n\nexport function configDir() {\n  const home = homedir();\n  if (platform() === \"win32\") {\n    return join(process.env.APPDATA || join(home, \"AppData\", \"Roaming\"), \"DigiConnectPrintStation\");\n  }\n  if (platform() === \"darwin\") {\n    return join(home, \"Library\", \"Application Support\", \"DigiConnectPrintStation\");\n  }\n  return join(process.env.XDG_CONFIG_HOME || join(home, \".config\"), \"digiconnect-print-station\");\n}\n\nexport function configPath() {\n  return join(configDir(), \"config.json\");\n}\n\n/**\n * Clean whatever was on disk, or in a form post, into a usable config.\n *\n * Written as a pure function so the rules can be tested without a filesystem:\n * every value a shop owner can type passes through here, and a mistyped poll\n * interval must never turn into an infinite loop.\n */\nexport function normalizeConfig(raw) {\n  const input = raw && typeof raw === \"object\" ? raw : {};\n\n  const serverUrl = String(input.serverUrl ?? DEFAULTS.serverUrl).trim().replace(/\\/+$/, \"\");\n\n  /*\n    \"Not provided\" is checked before Number, not after.\n\n    `Number(null)` and `Number(\"\")` are both 0, which is perfectly finite —\n    so a config file missing this field, or a form that left it blank, would\n    clamp to the two-second floor and quietly triple this shop's traffic to\n    the server forever.\n  */\n  const pollGiven = input.pollSeconds !== null && input.pollSeconds !== undefined && input.pollSeconds !== \"\";\n  const pollRaw = pollGiven ? Number(input.pollSeconds) : NaN;\n\n  return {\n    serverUrl: serverUrl || DEFAULTS.serverUrl,\n    agentToken: String(input.agentToken ?? \"\").trim(),\n    printerName: String(input.printerName ?? \"\").trim(),\n    // Clamped, not rejected: a shop owner who types 0 means \"as fast as\n    // possible\", and a shop owner who types 3600 has made a typo they should\n    // not have to diagnose from a stalled queue.\n    pollSeconds: Number.isFinite(pollRaw) ? Math.min(60, Math.max(2, Math.round(pollRaw))) : DEFAULTS.pollSeconds,\n    duplex: Boolean(input.duplex),\n    sumatraPath: String(input.sumatraPath ?? \"\").trim(),\n    seededFrom: String(input.seededFrom ?? \"\").trim(),\n    pendingToken: String(input.pendingToken ?? \"\").trim(),\n  };\n}\n\n/** Everything that must be true before the loop is allowed to start. */\nexport function configProblems(config) {\n  const problems = [];\n  if (!config.agentToken) problems.push(\"Paste the key from your DigiConnect partner dashboard.\");\n  else if (!config.agentToken.startsWith(\"dcp_\")) problems.push(\"That key does not look right — it should start with dcp_.\");\n  if (!config.printerName) problems.push(\"Choose the printer that should print the jobs.\");\n  if (!/^https?:\\/\\//i.test(config.serverUrl)) problems.push(\"The server address must start with http:// or https://.\");\n  return problems;\n}\n\nexport function isReady(config) {\n  return configProblems(config).length === 0;\n}\n\n/**\n * The settings that came inside the download, if any.\n *\n * A partner who downloads from their own dashboard gets a bundle with their\n * key and their site address already in it, so there is nothing to paste and\n * nothing to mistype.\n */\nfunction bundledConfig() {\n  try {\n    const beside = join(dirname(fileURLToPath(import.meta.url)), \"..\", \"config.json\");\n    if (!existsSync(beside)) return null;\n    return JSON.parse(readFileSync(beside, \"utf8\"));\n  } catch {\n    return null;\n  }\n}\n\nfunction readStored() {\n  const path = configPath();\n  if (!existsSync(path)) return null;\n  try {\n    const parsed = JSON.parse(readFileSync(path, \"utf8\"));\n    return parsed && typeof parsed === \"object\" ? parsed : null;\n  } catch {\n    // A corrupt file must not stop the shop from opening.\n    return null;\n  }\n}\n\n/**\n * The settings this computer runs on.\n *\n * The awkward case, and the one that actually bit a shop: a partner who had\n * already set the program up by hand downloaded a fresh bundle. Downloading\n * issues a new key and retires the old one — so the saved settings now held a\n * key certain to be refused, while the working key sat unread in the folder\n * they had just double-clicked. \"Your key was refused\", on the very action\n * meant to make keys somebody else's problem.\n *\n * So a bundle's key beats a saved one — but only once per bundle, and only\n * the key. Which printer this shop picked on this computer is not something a\n * download knows, and not something it should overwrite.\n */\nexport function loadConfig() {\n  const stored = readStored();\n  const bundled = bundledConfig();\n  const bundledToken = String(bundled?.agentToken ?? \"\").trim();\n\n  if (!stored) {\n    // Written out now, so the first save from the settings page edits a real\n    // file rather than re-seeding from the folder on every restart.\n    return bundled ? saveConfig({ ...bundled, seededFrom: bundledToken }) : normalizeConfig({});\n  }\n\n  if (bundledToken && bundledToken !== String(stored.seededFrom ?? \"\").trim()) {\n    return saveConfig({\n      ...stored,\n      agentToken: bundledToken,\n      serverUrl: bundled.serverUrl || stored.serverUrl,\n      seededFrom: bundledToken,\n    });\n  }\n\n  return normalizeConfig(stored);\n}\n\n/** Did this start take its key from the folder it was run out of? */\nexport function adoptedBundledKey(config, bundled = bundledConfig()) {\n  const token = String(bundled?.agentToken ?? \"\").trim();\n  return Boolean(token) && token === config.agentToken && token === config.seededFrom;\n}\n\n\nexport function saveConfig(config) {\n  const clean = normalizeConfig(config);\n  const path = configPath();\n  mkdirSync(dirname(path), { recursive: true });\n  writeFileSync(path, JSON.stringify(clean, null, 2), { mode: 0o600 });\n  return clean;\n}\n\n/** The config as it is safe to show on a screen or paste into a support chat. */\nexport function redactConfig(config) {\n  const token = config.agentToken;\n  return {\n    ...config,\n    agentToken: token ? `${token.slice(0, 8)}…${token.slice(-4)}` : \"\",\n    pendingToken: config.pendingToken ? \"…\" : \"\",\n    seededFrom: config.seededFrom ? \"…\" : \"\",\n  };\n}\n",
  "lib/api.mjs": "import { PRINT_STATION_VERSION } from \"./version.mjs\";\n\n/**\n * Everything this program says to the server.\n *\n * Four calls, and nothing else. Written against the endpoints in\n * src/app/api/print/agent/ — if one of those changes shape, this file is the\n * only place that has to follow.\n */\n\nexport class ApiError extends Error {\n  constructor(message, status) {\n    super(message);\n    this.name = \"ApiError\";\n    this.status = status;\n  }\n}\n\n/**\n * Whether a failure is worth trying again.\n *\n * A wrong key will be just as wrong in five seconds, and retrying it forever\n * fills a log with noise that hides the real problem. A timeout or a 502 is a\n * shop's broadband, and giving up on those would mean walking to the computer\n * every time the wifi blinked.\n */\nexport function isRetryable(status) {\n  if (status === undefined || status === null) return true; // network-level: no reply at all\n  if (status === 408 || status === 425 || status === 429) return true;\n  return status >= 500;\n}\n\n/** Back off after repeated failures, but never so far that a shop stalls. */\nexport function backoffSeconds(consecutiveFailures, base = 5) {\n  const capped = Math.min(6, Math.max(0, consecutiveFailures));\n  return Math.min(120, base * 2 ** capped);\n}\n\n\n/**\n * Is this redirect still the same website?\n *\n * rnos.in answers a request for the bare domain with a 307 to www.rnos.in.\n * Those are different origins, so `fetch` obeys the spec and strips the\n * Authorization header before following — the server then sees no key at all\n * and says the key was refused. Every key a shop tried was refused for this\n * reason, correct ones included, and nothing on either side could tell.\n *\n * So the redirect is followed by hand, with the header re-attached — but only\n * when it stays on the same site. A credential must never be replayed to\n * wherever a redirect happens to point.\n */\nexport function sameSite(fromUrl, toUrl) {\n  try {\n    const bare = (url) => new URL(url).hostname.toLowerCase().replace(/^www\\./, \"\");\n    return bare(fromUrl) === bare(toUrl);\n  } catch {\n    return false;\n  }\n}\n\n/** Where a redirect actually points, resolving a relative Location. */\nexport function redirectTarget(currentUrl, location) {\n  if (!location) return null;\n  try {\n    return new URL(location, currentUrl).toString();\n  } catch {\n    return null;\n  }\n}\n\nexport function createApi({ serverUrl, agentToken, fetchImpl = fetch, timeoutMs = 30_000 }) {\n  const base = String(serverUrl).replace(/\\/+$/, \"\");\n\n  async function call(path, { method = \"GET\", body } = {}) {\n    const controller = new AbortController();\n    const timer = setTimeout(() => controller.abort(), timeoutMs);\n\n    try {\n      const send = (url) =>\n        fetchImpl(url, {\n          method,\n          headers: {\n            Authorization: `Bearer ${agentToken}`,\n            // So the partner panel can say which version this PC runs.\n            \"X-Agent-Version\": PRINT_STATION_VERSION,\n            ...(body ? { \"Content-Type\": \"application/json\" } : {}),\n          },\n          body: body ? JSON.stringify(body) : undefined,\n          signal: controller.signal,\n          // Handled below rather than by fetch, so the credential survives.\n          redirect: \"manual\",\n        });\n\n      let url = `${base}${path}`;\n      let response = await send(url);\n\n      /*\n        Follow at most a couple of hops, and only within the same site.\n\n        Two is enough for the real case (bare domain to www, or http to\n        https) and a low enough ceiling that a redirect loop cannot spin\n        here. A hop that leaves the site is not followed with the key\n        attached — that would hand a shop's credential to whoever the\n        Location pointed at.\n      */\n      for (let hop = 0; hop < 2 && response.status >= 300 && response.status < 400; hop += 1) {\n        const next = redirectTarget(url, response.headers?.get?.(\"location\"));\n        if (!next || !sameSite(url, next)) break;\n        url = next;\n        response = await send(url);\n      }\n\n      const text = await response.text();\n      let json = null;\n      try {\n        json = text ? JSON.parse(text) : null;\n      } catch {\n        json = null;\n      }\n\n      if (!response.ok) {\n        throw new ApiError(json?.error || `Server replied ${response.status}`, response.status);\n      }\n      return json ?? {};\n    } finally {\n      clearTimeout(timer);\n    }\n  }\n\n  return {\n    /** Jobs waiting at this station. Also the heartbeat the dashboard reads. */\n    listJobs: (printers = []) => {\n      const query = printers.length ? `?printers=${encodeURIComponent(printers.join(\",\"))}` : \"\";\n      return call(`/api/print/agent/jobs${query}`);\n    },\n\n    /** Take a job, and get a download link that expires in five minutes. */\n    claim: (jobId) => call(\"/api/print/agent/claim-job\", { method: \"POST\", body: { job_id: jobId } }),\n\n    /** \"Is this key any good, and whose counter is it?\" */\n    whoami: () => call(\"/api/print/agent/whoami\"),\n\n    /** The current program files, for updating in place (see self-update.mjs). */\n    fetchUpdate: () => call(\"/api/print/agent/update\"),\n\n    /** Swap the zip's key for one only this computer knows (see secure-key.mjs). */\n    rotateKey: (newKeyHash) =>\n      call(\"/api/print/agent/rotate-key\", { method: \"POST\", body: { new_key_hash: newKeyHash } }),\n\n    /** Say what happened. The customer's screen is watching this. */\n    report: (jobId, status, errorMessage) =>\n      call(\"/api/print/agent/update-status\", {\n        method: \"POST\",\n        body: { job_id: jobId, status, error_message: errorMessage ?? \"\" },\n      }),\n  };\n}\n",
  "lib/worker.mjs": "import { mkdtempSync, rmSync, writeFileSync } from \"node:fs\";\nimport { tmpdir } from \"node:os\";\nimport { join } from \"node:path\";\n\nimport { isNewer } from \"./self-update.mjs\";\nimport { backoffSeconds, isRetryable } from \"./api.mjs\";\n\n/**\n * The loop: ask for work, take it, print it, say what happened.\n *\n * Deliberately dull. The interesting decisions — which job to take next, when\n * to back off, whether a failure is the shop's or the server's — are pure\n * functions above the loop so they can be tested without a printer, a network\n * or a clock.\n */\n\n/**\n * Which job to print next.\n *\n * Oldest first, because the customer who has been waiting longest is the one\n * about to ask. Jobs another agent already holds a live claim on are skipped:\n * the server would refuse the claim anyway, and trying wastes the interval a\n * waiting customer is counting.\n */\nexport function nextJob(jobs, now = Date.now()) {\n  const available = (Array.isArray(jobs) ? jobs : []).filter((job) => {\n    if (!job || !job.id) return false;\n    if (!job.claimed_by_agent) return true;\n    const expiry = job.claim_expires_at ? Date.parse(job.claim_expires_at) : NaN;\n    return Number.isFinite(expiry) && expiry < now;\n  });\n\n  available.sort((a, b) => Date.parse(a.created_at ?? 0) - Date.parse(b.created_at ?? 0));\n  return available[0] ?? null;\n}\n\n/**\n * What to tell the shop owner when something breaks.\n *\n * A shop owner is not going to read a stack trace, and \"Error: ECONNREFUSED\"\n * on a screen behind a counter is the same as no message at all. Each of\n * these names the thing they can actually go and fix.\n */\nexport function describeFailure(error) {\n  const status = error?.status;\n  const raw = String(error?.message ?? error ?? \"Something went wrong\");\n\n  if (status === 401) {\n    /*\n      Almost always the same story: a newer download was made, which issues a\n      new key and retires this one, and the older folder is still the one\n      being run. Naming that is far more use than \"issue a new one\", which is\n      what this used to say and what sent a shop round the loop again.\n    */\n    return \"Your key was refused. A newer download replaced it — run the newest downloaded folder, or download again from your dashboard.\";\n  }\n  if (status === 409) return \"Another computer took that job first. Nothing to do.\";\n  if (status === 404) return \"That job is no longer on the server.\";\n  if (status === 503) return \"The server is busy. Trying again shortly.\";\n  if (/ENOTFOUND|EAI_AGAIN|ECONNREFUSED|ECONNRESET|abort|network|fetch failed/i.test(raw)) {\n    return \"No internet. Jobs will print as soon as the connection is back.\";\n  }\n  if (/printer|spool|lp:|no such (file|printer)/i.test(raw)) {\n    return \"The printer did not accept the job. Check it is switched on, has paper, and is not showing an error.\";\n  }\n  return raw.slice(0, 200);\n}\n\n/** A failure that means \"stop and ask a human\" rather than \"try again\". */\nexport function isFatal(error) {\n  return error?.status === 401 || error?.status === 403;\n}\n\n/**\n * Download a claimed file to a temporary folder.\n *\n * Written to disk because operating system print commands take a path, not a\n * stream — and deleted in a `finally` regardless of how printing went. The\n * shop's promise to its customers is that nothing of theirs stays on this\n * computer, and a file left behind by a failed print would break it quietly.\n */\nexport async function downloadToTemp(url, fileName, fetchImpl = fetch) {\n  const response = await fetchImpl(url);\n  if (!response.ok) throw new Error(`Could not download the file (${response.status})`);\n\n  const buffer = Buffer.from(await response.arrayBuffer());\n  const folder = mkdtempSync(join(tmpdir(), \"dcps-\"));\n  // The server's name for the file is used only for its extension: a file\n  // name arrives from a customer's device and must never decide a path.\n  const extension = /\\.([a-z0-9]{1,5})$/i.exec(String(fileName ?? \"\"))?.[1]?.toLowerCase() ?? \"pdf\";\n  const path = join(folder, `job.${extension.replace(/[^a-z0-9]/g, \"\") || \"pdf\"}`);\n  writeFileSync(path, buffer);\n\n  return {\n    path,\n    cleanup: () => {\n      try {\n        rmSync(folder, { recursive: true, force: true });\n      } catch {\n        /* A file we cannot delete is worth no crash, but it is worth a log. */\n      }\n    },\n  };\n}\n\n/**\n * One job, start to finish.\n *\n * Every exit path reports to the server. A job that is claimed and never\n * reported sits as \"printing\" on the customer's screen until its claim\n * expires — five silent minutes in front of somebody who has already paid.\n */\nexport async function runJob({ api, job, print, log, download = downloadToTemp }) {\n  let claim;\n  try {\n    claim = await api.claim(job.id);\n  } catch (error) {\n    if (error?.status === 409) {\n      log(\"info\", `Job ${job.job_number ?? job.id} was taken by another computer.`);\n      return { outcome: \"skipped\" };\n    }\n    throw error;\n  }\n\n  const file = claim?.file;\n  if (!file?.download_url) {\n    await api.report(job.id, \"failed\", \"The server did not send a file to print.\");\n    return { outcome: \"failed\", message: \"No file on the job.\" };\n  }\n\n  let temp = null;\n  try {\n    temp = await download(file.download_url, file.file_name);\n    log(\"info\", `Printing ${job.job_number ?? job.id}: ${job.copies ?? 1} × ${job.pages ?? \"?\"} pages, ${job.paper_size ?? \"A4\"} ${job.color_mode ?? \"mono\"}.`);\n    await print({ filePath: temp.path, job });\n    await api.report(job.id, \"printed\");\n    log(\"success\", `Printed ${job.job_number ?? job.id}.`);\n    return { outcome: \"printed\" };\n  } catch (error) {\n    const message = describeFailure(error);\n    log(\"error\", `Job ${job.job_number ?? job.id} failed: ${message}`);\n    // Reported as failed so the job returns to the queue and the customer is\n    // told, rather than being left to time out. A failure to report is\n    // swallowed: it must not mask the original problem in the log.\n    await api.report(job.id, \"failed\", message).catch(() => {});\n    return { outcome: \"failed\", message };\n  } finally {\n    temp?.cleanup();\n  }\n}\n\n/**\n * Which printer a job goes to.\n *\n * The partner picks printers in the website panel — one for everything, and\n * optionally a separate one for colour. A choice is used only when this\n * computer actually has a printer by that name: a panel choice made for a PC\n * that has since been replaced must not send jobs into a queue that does not\n * exist. Otherwise the printer chosen on this computer's own setup page.\n */\nexport function choosePrinter({ job, serverPrinter, serverColorPrinter, printers = [], fallback }) {\n  const has = (name) => Boolean(name) && (printers.length === 0 || printers.includes(name));\n  if (job?.color_mode === \"color\" && has(serverColorPrinter)) return serverColorPrinter;\n  if (has(serverPrinter)) return serverPrinter;\n  return fallback;\n}\n\n/**\n * The polling loop.\n *\n * `state` is passed in rather than held here so the setup page can read what\n * the loop is doing — connected or not, what it last printed, what went\n * wrong — without the two sharing anything more than an object.\n */\nexport function createWorker({\n  api,\n  config,\n  print,\n  log,\n  state,\n  sleep = defaultSleep,\n  printers = [],\n  getPrinters,\n  onUpdateRequested,\n  currentVersion,\n}) {\n  let running = false;\n  let stopped = false;\n\n  async function tick() {\n    // A getter, so a printer plugged in after start-up is reported without a\n    // restart; the plain array stays for callers (and tests) that pass one.\n    const current = typeof getPrinters === \"function\" ? getPrinters() : printers;\n    const { jobs, station, update } = await api.listJobs(current);\n    state.connected = true;\n    // Shown on the shop's own screen so a partner can see the key landed on\n    // their counter rather than somebody else's.\n    if (station?.display_name) state.stationName = station.display_name;\n    // The partner's choice from the website panel; see choosePrinter.\n    if (station) {\n      state.serverPrinter = station.printer_name || null;\n      state.serverColorPrinter = station.color_printer_name || null;\n    }\n    state.lastPollAt = new Date().toISOString();\n\n    /*\n      A newer connector exists. Shown on the local page either way; installed\n      only when the partner asked for it from their panel. Checked between\n      jobs, never during one, so an update cannot cut a print in half.\n    */\n    if (update?.latest && currentVersion) {\n      state.latestVersion = update.latest;\n      state.updateAvailable = isNewer(update.latest, currentVersion);\n      if (state.updateAvailable && update.requested && typeof onUpdateRequested === \"function\") {\n        await onUpdateRequested(update.latest);\n        return false;\n      }\n    }\n    state.queued = Array.isArray(jobs) ? jobs.length : 0;\n\n    const job = nextJob(jobs);\n    if (!job) return false;\n\n    const result = await runJob({ api, job, print, log });\n    if (result.outcome === \"printed\") state.printed += 1;\n    if (result.outcome === \"failed\") state.failed += 1;\n    return true;\n  }\n\n  async function loop() {\n    running = true;\n    let failures = 0;\n\n    while (!stopped) {\n      try {\n        const didWork = await tick();\n        failures = 0;\n        state.lastError = null;\n        // After a print, look again immediately: two customers in a queue\n        // should not wait an interval each.\n        await sleep(didWork ? 250 : config.pollSeconds * 1000);\n      } catch (error) {\n        state.connected = false;\n        state.lastError = describeFailure(error);\n\n        if (isFatal(error)) {\n          log(\"error\", state.lastError);\n          state.stoppedReason = state.lastError;\n          break;\n        }\n        if (!isRetryable(error?.status)) {\n          log(\"error\", state.lastError);\n        }\n\n        failures += 1;\n        const wait = backoffSeconds(failures, config.pollSeconds);\n        if (failures === 1 || failures % 5 === 0) log(\"warn\", `${state.lastError} Retrying in ${wait}s.`);\n        await sleep(wait * 1000);\n      }\n    }\n\n    running = false;\n  }\n\n  return {\n    start: () => {\n      if (running) return;\n      stopped = false;\n      void loop();\n    },\n    stop: () => {\n      stopped = true;\n    },\n    isRunning: () => running,\n    tick,\n  };\n}\n\nfunction defaultSleep(ms) {\n  return new Promise((resolve) => setTimeout(resolve, ms));\n}\n\n/**\n * Answer \"why isn't this working\" once, instead of guessing at it.\n *\n * Returned as a list of plain findings a shop owner can act on, in the order\n * they have to be fixed: an unreachable website makes every later question\n * meaningless, and a dead key makes the printer question moot.\n *\n * The checks deliberately name the values in play — the address being called,\n * the tail of the key being presented — because \"your key was refused\" with\n * no sight of which key or which address is what sent a real shop round the\n * same loop for an afternoon.\n */\nexport async function diagnose({ api, config, printers = [] }) {\n  const findings = [];\n  const add = (level, text) => findings.push({ level, text });\n\n  add(\"info\", `Calling ${config.serverUrl}`);\n  add(\"info\", `Using key ${keyTail(config.agentToken)}`);\n\n  let identity = null;\n  try {\n    identity = await api.whoami();\n  } catch (error) {\n    const status = error?.status;\n\n    if (status === 401) {\n      add(\"error\", \"This key is not the current one for any counter.\");\n      add(\"fix\", \"Open your dashboard, press 'Lost the key? Issue a new one', and paste the key it shows into the box above.\");\n      return findings;\n    }\n    if (status === 503) {\n      add(\"warn\", \"The website cannot reach its database. Nothing is wrong with your key.\");\n      add(\"fix\", \"Leave this running — it will pick up on its own.\");\n      return findings;\n    }\n    if (status === 404) {\n      // The site is up but does not have this endpoint, which means it is\n      // running a version older than this program.\n      add(\"warn\", \"The website answered, but does not know this program yet.\");\n      add(\"fix\", \"The site is still updating. Try again in a few minutes.\");\n      return findings;\n    }\n\n    add(\"error\", describeFailure(error));\n    add(\"fix\", \"Check the website address above, and that this computer is online.\");\n    return findings;\n  }\n\n  add(\"ok\", identity?.message ?? \"Key accepted.\");\n  if (identity?.acceptingOrders === false) {\n    add(\"fix\", \"Switch your counter back on from the dashboard, or customers cannot pay.\");\n  }\n\n  if (!config.printerName) {\n    add(\"error\", \"No printer chosen.\");\n    add(\"fix\", \"Pick your printer from the list above and save.\");\n  } else if (printers.length && !printers.includes(config.printerName)) {\n    // A printer that was unplugged, renamed, or removed. The name saved here\n    // will never match again, and jobs would fail one at a time.\n    add(\"error\", `\"${config.printerName}\" is not on this computer any more.`);\n    add(\"fix\", \"Pick the printer again from the list above and save.\");\n  } else if (config.printerName) {\n    add(\"ok\", `Printing to \"${config.printerName}\".`);\n  }\n\n  return findings;\n}\n\n/** Enough of a key to recognise it, never enough to use it. */\nexport function keyTail(token) {\n  const value = String(token ?? \"\").trim();\n  if (!value) return \"(none)\";\n  return value.length <= 12 ? \"(too short to be a key)\" : `${value.slice(0, 8)}…${value.slice(-4)}`;\n}\n",
  "lib/printer.mjs": "import { execFile } from \"node:child_process\";\nimport { existsSync, renameSync, rmSync, writeFileSync } from \"node:fs\";\nimport { platform } from \"node:os\";\nimport { dirname, join } from \"node:path\";\nimport { fileURLToPath } from \"node:url\";\n\n/**\n * The part that puts ink on paper.\n *\n * Printing a PDF without a human clicking anything is the one genuinely\n * awkward thing this program does, and it is awkward differently on every\n * operating system. The decisions are kept as pure functions here so they can\n * be tested on a machine with no printer attached; only `run` touches the\n * world.\n */\n\nconst IS_WINDOWS = platform() === \"win32\";\nconst IS_MAC = platform() === \"darwin\";\n\n/**\n * Where the printing helper might be, best first.\n *\n * The first entry is the one that matters: the installer drops a copy beside\n * the program, so a shop owner never has to go and find it. The rest are the\n * places a normal install puts it, kept so a computer that already had it\n * does not download a second copy.\n */\nexport function appFolderSumatra() {\n  try {\n    return join(dirname(fileURLToPath(import.meta.url)), \"..\", \"SumatraPDF.exe\");\n  } catch {\n    return \"\";\n  }\n}\n\nexport const SUMATRA_CANDIDATES = [\n  \"C:\\\\Program Files\\\\SumatraPDF\\\\SumatraPDF.exe\",\n  \"C:\\\\Program Files (x86)\\\\SumatraPDF\\\\SumatraPDF.exe\",\n  `${process.env.LOCALAPPDATA ?? \"\"}\\\\SumatraPDF\\\\SumatraPDF.exe`,\n  `${process.env.LOCALAPPDATA ?? \"\"}\\\\Programs\\\\SumatraPDF\\\\SumatraPDF.exe`,\n];\n\nexport function findSumatra(configuredPath, exists = existsSync) {\n  const configured = String(configuredPath ?? \"\").trim();\n  if (configured && exists(configured)) return configured;\n\n  const beside = appFolderSumatra();\n  if (beside && exists(beside)) return beside;\n\n  return SUMATRA_CANDIDATES.find((candidate) => candidate.length > 20 && exists(candidate)) ?? null;\n}\n\n/**\n * The arguments that print a PDF silently through SumatraPDF.\n *\n * `-print-to` names the printer, `-silent` suppresses its window and every\n * error dialog, and `-exit-when-done` stops a shop ending the day with two\n * hundred open viewers. The print settings string carries copies, paper size\n * and colour, because SumatraPDF has no separate flags for them.\n */\nexport function sumatraArgs({ filePath, printerName, job, duplex = false }) {\n  const settings = [`${Math.max(1, job.copies ?? 1)}x`, \"fit\"];\n  if (String(job.paper_size ?? \"A4\").toUpperCase() === \"A3\") settings.push(\"paper=A3\");\n  else settings.push(\"paper=A4\");\n  settings.push(job.color_mode === \"color\" ? \"color\" : \"monochrome\");\n  if (duplex) settings.push(\"duplex\");\n\n  return [\"-print-to\", printerName, \"-print-settings\", settings.join(\",\"), \"-silent\", \"-exit-when-done\", filePath];\n}\n\n/**\n * The CUPS command, used on macOS and Linux.\n *\n * `lp` takes each setting as its own option, which is why this does not share\n * a shape with the Windows path — pretending they were the same would mean\n * one of them silently ignoring copies.\n */\nexport function lpArgs({ filePath, printerName, job, duplex = false }) {\n  const args = [\"-d\", printerName, \"-n\", String(Math.max(1, job.copies ?? 1))];\n  args.push(\"-o\", `media=${String(job.paper_size ?? \"A4\").toUpperCase() === \"A3\" ? \"A3\" : \"A4\"}`);\n  args.push(\"-o\", job.color_mode === \"color\" ? \"ColorModel=RGB\" : \"ColorModel=Gray\");\n  if (duplex) args.push(\"-o\", \"sides=two-sided-long-edge\");\n  args.push(filePath);\n  return args;\n}\n\n/**\n * Pick how to print, given what is installed.\n *\n * Returned as data rather than executed, so the choice is testable and so the\n * setup page can tell a shop owner which route their machine will take before\n * a customer is standing there waiting.\n */\nexport function choosePrintCommand({ filePath, printerName, job, config, os = platform(), exists = existsSync }) {\n  if (os === \"win32\") {\n    /*\n      Photos first, because Windows can print them itself.\n\n      This is not a fallback — it is better than handing an image to a\n      viewer, which is how a real job died: no application on that computer\n      was associated with .webp, and there was nothing to hand it to.\n    */\n    if (isImageFile(filePath)) {\n      return {\n        kind: \"dotnet-image\",\n        command: \"powershell.exe\",\n        args: [\"-NoProfile\", \"-NonInteractive\", \"-Command\", imagePrintScript({ filePath, printerName, job })],\n      };\n    }\n\n    const sumatra = findSumatra(config?.sumatraPath, exists);\n    if (sumatra) {\n      return { kind: \"sumatra\", command: sumatra, args: sumatraArgs({ filePath, printerName, job, duplex: config?.duplex }) };\n    }\n    /*\n      The fallback when SumatraPDF is not there.\n\n      Windows' PrintTo verb honours the printer and nothing else — it cannot\n      be told the paper size or whether to use colour. So those are set on the\n      printer itself first, with Windows' own Set-PrintConfiguration, and put\n      back afterwards. Copies are still sent as separate calls by the caller,\n      because no amount of printer configuration adds a copy count to a shell\n      verb.\n\n      This route is second choice, not a broken one: a customer who paid for\n      an A3 colour page gets an A3 colour page. What it cannot promise is\n      speed, since it opens the system's PDF viewer once per copy.\n    */\n    return {\n      kind: \"shell-verb\",\n      command: \"powershell.exe\",\n      args: [\"-NoProfile\", \"-NonInteractive\", \"-Command\", shellVerbScript({ filePath, printerName, job })],\n      /*\n        Honest about what this can and cannot do.\n\n        It works only if some application on that computer has registered\n        itself to print this file type. For PDFs that usually means Adobe\n        Reader; Edge does not. When nothing has, the job fails with a message\n        about no associated application — which is what happened at a real\n        counter while the log claimed this route \"works fine\".\n      */\n      degraded:\n        \"No fast printing helper found, so this goes through whichever app opens PDFs on this computer. If nothing does, PDFs will fail — photos are unaffected.\",\n    };\n  }\n\n  return { kind: IS_MAC ? \"lp\" : \"lp\", command: \"lp\", args: lpArgs({ filePath, printerName, job, duplex: config?.duplex }) };\n}\n\n/** Photos, which Windows can print itself — see below. */\nconst IMAGE_EXTENSIONS = [\"jpg\", \"jpeg\", \"png\", \"webp\", \"bmp\", \"gif\", \"tif\", \"tiff\"];\n\nexport function isImageFile(filePath) {\n  const extension = /\\.([a-z0-9]+)$/i.exec(String(filePath ?? \"\"))?.[1]?.toLowerCase();\n  return Boolean(extension && IMAGE_EXTENSIONS.includes(extension));\n}\n\n/**\n * Print a photo using Windows' own drawing library.\n *\n * The lesson from a real counter: a customer paid for a .webp and the job\n * died on \"No application is associated with the specified file for this\n * operation.\" Windows has no PrintTo handler for webp — and often none for\n * PDF either — so handing the file to the shell was never the safe fallback\n * I claimed it was.\n *\n * .NET can print an image directly, with no helper application involved at\n * all. It also takes the copies, the paper size and the colour setting\n * properly, which the shell verb never could. Photos and screenshots are most\n * of what a counter prints, so this is the path that matters most.\n */\nexport function imagePrintScript({ filePath, printerName, job }) {\n  const copies = Math.max(1, Math.min(99, Math.round(Number(job?.copies) || 1)));\n  const paper = String(job?.paper_size ?? \"A4\").toUpperCase() === \"A3\" ? \"A3\" : \"A4\";\n  const colour = job?.color_mode === \"color\" ? \"$true\" : \"$false\";\n\n  return [\n    \"$ErrorActionPreference = 'Stop'\",\n    \"try {\",\n    \"  Add-Type -AssemblyName System.Drawing\",\n    `  $script:img = [System.Drawing.Image]::FromFile(${quoteForPowerShell(filePath)})`,\n    \"  $doc = New-Object System.Drawing.Printing.PrintDocument\",\n    `  $doc.PrinterSettings.PrinterName = ${quoteForPowerShell(printerName)}`,\n    // A printer name that no longer matches anything must say so, rather than\n    // silently printing to whatever Windows considers the default.\n    `  if (-not $doc.PrinterSettings.IsValid) { throw 'Printer not found: ' + ${quoteForPowerShell(printerName)} }`,\n    `  $doc.PrinterSettings.Copies = ${copies}`,\n    `  $doc.DefaultPageSettings.Color = ${colour}`,\n    `  $paper = $doc.PrinterSettings.PaperSizes | Where-Object { $_.PaperName -eq '${paper}' } | Select-Object -First 1`,\n    \"  if ($paper) { $doc.DefaultPageSettings.PaperSize = $paper }\",\n    \"  $doc.DocumentName = 'DigiConnect print'\",\n    \"  $doc.add_PrintPage({\",\n    \"    param($sender, $e)\",\n    // Fit inside the printable area without distorting it: a customer's\n    // photo stretched to the page edges is a wasted sheet they paid for.\n    \"    $area = $e.MarginBounds\",\n    \"    $scale = [Math]::Min($area.Width / $script:img.Width, $area.Height / $script:img.Height)\",\n    \"    $w = [int]($script:img.Width * $scale)\",\n    \"    $h = [int]($script:img.Height * $scale)\",\n    \"    $x = $area.X + [int](($area.Width - $w) / 2)\",\n    \"    $y = $area.Y + [int](($area.Height - $h) / 2)\",\n    \"    $e.Graphics.DrawImage($script:img, $x, $y, $w, $h)\",\n    \"    $e.HasMorePages = $false\",\n    \"  })\",\n    \"  $doc.Print()\",\n    \"  $doc.Dispose()\",\n    \"  $script:img.Dispose()\",\n    \"} catch {\",\n    // Without an explicit non-zero exit, powershell.exe reports success and\n    // the shop is told the page printed when it did not.\n    \"  Write-Error $_.Exception.Message\",\n    \"  exit 1\",\n    \"}\",\n  ].join(\"\\n\");\n}\n\n/**\n * The PowerShell that prints one copy through Windows' own viewer.\n *\n * Built as a string here rather than run, so the exact commands a shop's\n * computer will execute can be checked in a test on a machine with no\n * printer. Every step that touches printer settings is wrapped: a printer\n * that refuses to be reconfigured should still print the page, on whatever\n * its defaults are, rather than fail the job outright.\n */\nexport function shellVerbScript({ filePath, printerName, job }) {\n  const printer = quoteForPowerShell(printerName);\n  const paper = String(job?.paper_size ?? \"A4\").toUpperCase() === \"A3\" ? \"A3\" : \"A4\";\n  const colour = job?.color_mode === \"color\" ? \"$true\" : \"$false\";\n\n  return [\n    \"$ErrorActionPreference = 'Stop'\",\n    `try { Set-PrintConfiguration -PrinterName ${printer} -PaperSize ${paper} -Color ${colour} } catch { }`,\n    `$p = Start-Process -FilePath ${quoteForPowerShell(filePath)} -Verb PrintTo -ArgumentList ${printer} -PassThru`,\n    \"if ($p) { Wait-Process -Id $p.Id -Timeout 120 -ErrorAction SilentlyContinue }\",\n    // The viewer can linger after the spool; closing it keeps a shop from\n    // ending the day behind two hundred open windows.\n    \"if ($p -and -not $p.HasExited) { Stop-Process -Id $p.Id -Force -ErrorAction SilentlyContinue }\",\n  ].join(\"; \");\n}\n\n/** Single-quote a value for PowerShell, doubling any quote inside it. */\nexport function quoteForPowerShell(value) {\n  return `'${String(value).replace(/'/g, \"''\")}'`;\n}\n\n/**\n * Is this actually a Windows program, or a 404 page wearing its name?\n *\n * A missed download that saved the site's HTML error page as SumatraPDF.exe\n * would be found by every later lookup and fail every print, with a message\n * about the printer rather than about the file. Every executable begins \"MZ\";\n * nothing else here does.\n */\nexport function looksLikeWindowsProgram(head) {\n  return Buffer.isBuffer(head) && head.length > 2 && head[0] === 0x4d && head[1] === 0x5a;\n}\n\n/**\n * Fetch the printing helper once, so no shop owner ever installs anything.\n *\n * Best effort by design: the program prints perfectly well without it through\n * Windows' own viewer, so every failure here logs a line and returns. The\n * file is written under a temporary name and only moved into place once it\n * has been checked, because a half-written or wrong file is worse than none.\n */\nexport async function ensurePrintHelper({ serverUrl, config, log, fetchImpl = fetch }) {\n  if (platform() !== \"win32\") return null;\n\n  const existing = findSumatra(config?.sumatraPath);\n  if (existing) return existing;\n\n  const target = appFolderSumatra();\n  if (!target) return null;\n  const temporary = `${target}.part`;\n\n  try {\n    const response = await fetchImpl(`${String(serverUrl).replace(/\\/+$/, \"\")}/print-station/SumatraPDF.exe`);\n    if (!response.ok) throw new Error(String(response.status));\n\n    const bytes = Buffer.from(await response.arrayBuffer());\n    if (!looksLikeWindowsProgram(bytes)) throw new Error(\"not a program\");\n\n    writeFileSync(temporary, bytes);\n    renameSync(temporary, target);\n    log?.(\"info\", \"Fast printing helper installed.\");\n    return target;\n  } catch {\n    try {\n      rmSync(temporary, { force: true });\n    } catch {\n      /* Nothing to clean up. */\n    }\n    /*\n      Said precisely, because the old wording — \"works fine\" — was read by a\n      shop owner as reassurance right before a job failed for exactly the\n      reason this line should have warned about.\n    */\n    log?.(\n      \"info\",\n      \"No fast printing helper. Photos print normally; PDFs need an app on this computer that can print them.\",\n    );\n    return null;\n  }\n}\n\n/* ─────────────────────────────────────────────────────────────────────────\n   Talking to the machine\n   ───────────────────────────────────────────────────────────────────────── */\n\nfunction run(command, args, timeout = 120_000) {\n  return new Promise((resolve, reject) => {\n    execFile(command, args, { timeout, windowsHide: true }, (error, stdout, stderr) => {\n      if (error) {\n        reject(new Error(String(stderr || error.message).trim().slice(0, 400)));\n        return;\n      }\n      resolve(String(stdout));\n    });\n  });\n}\n\n/** Parse `wmic`/PowerShell printer output into names. */\nexport function parseWindowsPrinters(stdout) {\n  return String(stdout)\n    .split(/\\r?\\n/)\n    .map((line) => line.trim())\n    .filter((line) => line && line.toLowerCase() !== \"name\" && !/^-+$/.test(line));\n}\n\n/** Parse `lpstat -a` into names. CUPS puts the queue first, then prose. */\nexport function parseCupsPrinters(stdout) {\n  return String(stdout)\n    .split(/\\r?\\n/)\n    .map((line) => line.trim().split(/\\s+/)[0])\n    .filter(Boolean);\n}\n\n/** Every printer this computer can see, by the name the OS uses. */\nexport async function listPrinters() {\n  try {\n    if (IS_WINDOWS) {\n      const stdout = await run(\n        \"powershell.exe\",\n        [\"-NoProfile\", \"-NonInteractive\", \"-Command\", \"Get-Printer | Select-Object -ExpandProperty Name\"],\n        20_000,\n      );\n      return parseWindowsPrinters(stdout);\n    }\n    return parseCupsPrinters(await run(\"lpstat\", [\"-a\"], 20_000));\n  } catch {\n    // No printers is a state the setup page can show. An exception here would\n    // take the whole setup page down with it.\n    return [];\n  }\n}\n\n/**\n * The computer's own default printer, or null.\n *\n * Used once, at start-up, when no printer has been chosen yet: the program\n * starts printing to what the shop already prints to, so a fresh install\n * needs no setup page at all.\n */\nexport async function defaultPrinter() {\n  try {\n    if (IS_WINDOWS) {\n      const stdout = await run(\n        \"powershell.exe\",\n        [\n          \"-NoProfile\",\n          \"-NonInteractive\",\n          \"-Command\",\n          \"Get-CimInstance Win32_Printer -Filter 'Default=True' | Select-Object -ExpandProperty Name\",\n        ],\n        20_000,\n      );\n      return parseWindowsPrinters(stdout)[0] ?? null;\n    }\n    return parseCupsDefault(await run(\"lpstat\", [\"-d\"], 20_000));\n  } catch {\n    return null;\n  }\n}\n\n/** `lpstat -d` → \"system default destination: Name\". */\nexport function parseCupsDefault(stdout) {\n  const match = /destination:\\s*(\\S+)/i.exec(String(stdout));\n  return match ? match[1] : null;\n}\n\n/**\n * The printer to start with when none is configured.\n *\n * The OS default when it is a real printer; otherwise the first physical one,\n * skipping the virtual \"printers\" every Windows has, which would swallow a\n * paying customer's job into a PDF file or OneNote.\n */\nexport function pickStartupPrinter(printers, systemDefault) {\n  const virtual = /(pdf|xps|onenote|fax|send to|microsoft print)/i;\n  if (systemDefault && printers.includes(systemDefault) && !virtual.test(systemDefault)) return systemDefault;\n  return printers.find((name) => !virtual.test(name)) ?? null;\n}\n\n/**\n * Print one job's file.\n *\n * Resolves when the print command returns, which is when the file has been\n * handed to the spooler — not when the last page lands in the tray. No\n * consumer operating system reliably tells a program the latter, and claiming\n * otherwise in the customer's status would be a lie.\n */\nexport async function printFile({ filePath, printerName, job, config }) {\n  const plan = choosePrintCommand({ filePath, printerName, job, config });\n\n  /*\n    The .NET path prints every copy itself through PrinterSettings.Copies, so\n    it runs once. Looping it would charge a customer for three and give them\n    nine.\n  */\n  if (plan.kind === \"dotnet-image\") {\n    await run(plan.command, plan.args);\n    return plan;\n  }\n\n  if (plan.kind === \"shell-verb\") {\n    // This route cannot ask for copies, so it asks the same number of times.\n    const copies = Math.max(1, Math.min(20, job.copies ?? 1));\n    for (let index = 0; index < copies; index += 1) {\n      await run(plan.command, plan.args);\n    }\n    return plan;\n  }\n\n  await run(plan.command, plan.args);\n  return plan;\n}\n",
  "lib/page.mjs": "/**\n * The setup screen, served on this computer only.\n *\n * One HTML file with no build step and no dependencies, because the thing\n * standing between a shop and a working printer should not be a toolchain.\n * It looks like the DigiConnect dashboard on purpose: a partner who has just\n * copied their key from the website should recognise where they have landed.\n */\n\nexport function renderPage() {\n  return `<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n<title>DigiConnect Print Station</title>\n<style>\n  :root {\n    --ink: #0b1220; --body: #55617a; --line: rgba(15,32,73,.12);\n    --blue: linear-gradient(135deg,#1f4fd8,#3b82f6); --flame: #f4632e;\n    --ok: #0f9d58; --bg: #eef2fb;\n  }\n  * { box-sizing: border-box; }\n  /* Every pill here is display:inline-flex, which outranks the hidden\n     attribute's own rule and would leave an empty bubble on the screen. */\n  [hidden] { display: none !important; }\n  body { margin:0; background:\n      radial-gradient(1000px 600px at 15% -10%, #dfe8ff 0%, transparent 60%),\n      radial-gradient(800px 500px at 95% 0%, #ffe6dc 0%, transparent 55%), var(--bg);\n    font: 14px/1.55 system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif; color: var(--ink);\n    min-height: 100vh; padding: 28px 16px 64px; }\n  .wrap { max-width: 720px; margin: 0 auto; }\n  .card { background: rgba(255,255,255,.72); backdrop-filter: blur(18px);\n    border: 1px solid var(--line); border-radius: 20px; padding: 20px;\n    box-shadow: 0 18px 50px -30px rgba(15,32,73,.5); margin-bottom: 16px; }\n  h1 { font-size: 21px; margin: 0; letter-spacing: -.4px; }\n  h2 { font-size: 14px; margin: 0 0 12px; }\n  p { color: var(--body); margin: 6px 0 0; }\n  .head { display:flex; align-items:center; gap:12px; }\n  .mark { width:44px; height:44px; border-radius:14px; background: var(--blue); color:#fff;\n    display:grid; place-items:center; font-size:20px; flex:none; }\n  label { display:block; margin-top:14px; font-size:12px; font-weight:700; }\n  input, select { width:100%; margin-top:6px; padding:11px 12px; border-radius:12px;\n    border:1px solid var(--line); background:rgba(255,255,255,.9); font:inherit; color:var(--ink); }\n  input:focus, select:focus { outline:2px solid #3b82f6; outline-offset:1px; }\n  .row { display:flex; gap:10px; flex-wrap:wrap; margin-top:16px; }\n  button { border:0; border-radius:12px; padding:11px 18px; font:inherit; font-weight:700; cursor:pointer; }\n  .primary { background: var(--blue); color:#fff; }\n  .ghost { background: rgba(255,255,255,.9); border:1px solid var(--line); color:var(--body); }\n  button:disabled { opacity:.55; cursor:default; }\n  .pill { display:inline-flex; align-items:center; gap:7px; font-weight:800; font-size:12.5px;\n    padding:6px 12px; border-radius:999px; background:rgba(255,255,255,.9); border:1px solid var(--line); }\n  .dot { width:8px; height:8px; border-radius:50%; background:#c3cbdc; }\n  .on .dot { background: var(--ok); box-shadow:0 0 0 4px rgba(15,157,88,.15); }\n  .off .dot { background: var(--flame); box-shadow:0 0 0 4px rgba(244,99,46,.15); }\n  .stats { display:grid; grid-template-columns:repeat(3,1fr); gap:10px; margin-top:14px; }\n  .stat { background:rgba(255,255,255,.9); border:1px solid var(--line); border-radius:14px; padding:12px; }\n  .stat b { display:block; font-size:21px; letter-spacing:-.5px; }\n  .stat span { font-size:11.5px; color:var(--body); font-weight:600; }\n  .log { margin-top:14px; max-height:260px; overflow:auto; font:12px/1.6 ui-monospace, Menlo, Consolas, monospace; }\n  .log div { padding:4px 0; border-bottom:1px dashed var(--line); color:var(--body); }\n  .log .error { color:var(--flame); font-weight:700; }\n  .log .success { color:var(--ok); }\n  .log .warn { color:#b26a00; }\n  .update-box { margin-top:12px; display:flex; gap:12px; align-items:center; justify-content:space-between;\n    flex-wrap:wrap; border:1px solid #c7d2fe; background:#eef2ff; border-radius:10px; padding:10px 12px; font-size:14px; }\n  .update-box button { border:0; border-radius:8px; background:#1e293b; color:#fff; font-weight:700; padding:8px 14px; cursor:pointer; }\n  .warn-box { margin-top:12px; border-left:3px solid var(--flame); padding:10px 12px;\n    background:rgba(244,99,46,.07); border-radius:0 12px 12px 0; font-size:12.5px; }\n  /* Deliberately not \".mark\": that class is already the 44px header tile\n     above, and reusing it made every finding sprout a blue square. */\n  .findings { margin-top:14px; display:grid; gap:6px; }\n  .finding { display:grid; grid-template-columns:5.2rem 1fr; gap:10px; align-items:baseline;\n    padding:9px 12px; border-radius:10px; border:1px solid var(--line);\n    background:rgba(255,255,255,.92); font-size:12.5px; line-height:1.5; color:var(--body); }\n  .finding .tag { font-weight:800; font-size:10.5px; letter-spacing:.09em; text-transform:uppercase; }\n  .finding.ok    { border-left:3px solid var(--ok); }\n  .finding.ok    .tag { color:var(--ok); }\n  .finding.error { border-left:3px solid var(--flame); background:rgba(244,99,46,.06); }\n  .finding.error .tag, .finding.error span:last-child { color:var(--flame); font-weight:600; }\n  .finding.warn  { border-left:3px solid #b26a00; }\n  .finding.warn  .tag { color:#b26a00; }\n  .finding.info  { opacity:.85; }\n  .finding.info  .tag { color:var(--faint, #9aa4b8); }\n  .finding.fix   { border-left:3px solid #1f4fd8; background:rgba(31,79,216,.06); }\n  .finding.fix   .tag { color:#1f4fd8; }\n  .finding.fix   span:last-child { color:var(--ink); font-weight:600; }\n  .muted { font-size:12px; color:var(--body); }\n  a { color:#1f4fd8; }\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <div class=\"card\">\n    <div class=\"head\">\n      <span class=\"mark\">&#128424;</span>\n      <div>\n        <h1>DigiConnect Print Station</h1>\n        <p class=\"muted\">This computer prints what your customers order. <span id=\"version\"></span></p>\n      </div>\n    </div>\n    <div class=\"row\" id=\"status-row\">\n      <span class=\"pill\" id=\"conn\"><span class=\"dot\"></span><span id=\"conn-text\">Starting…</span></span>\n      <span class=\"pill\" id=\"station-pill\" hidden></span>\n    </div>\n    <div class=\"stats\">\n      <div class=\"stat\"><b id=\"s-queued\">0</b><span>Waiting</span></div>\n      <div class=\"stat\"><b id=\"s-printed\">0</b><span>Printed</span></div>\n      <div class=\"stat\"><b id=\"s-failed\">0</b><span>Failed</span></div>\n    </div>\n    <div class=\"warn-box\" id=\"problem\" hidden></div>\n    <div class=\"findings\" id=\"findings\" hidden></div>\n    <div class=\"update-box\" id=\"update-box\" hidden>\n      <span>Naya version <b id=\"update-version\"></b> available hai.</span>\n      <button type=\"button\" id=\"update-btn\">Update install karo</button>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h2>Settings</h2>\n    <form id=\"form\">\n      <label>Your key\n        <input name=\"agentToken\" id=\"agentToken\" placeholder=\"dcp_… (khali chhodiye to purani key hi rahegi)\" autocomplete=\"off\" spellcheck=\"false\" />\n      </label>\n      <p class=\"muted\">Copy it from your partner dashboard &rarr; Print counter. It is shown only once.</p>\n\n      <label>Printer\n        <select name=\"printerName\" id=\"printerName\"></select>\n      </label>\n\n      <label>Website address\n        <input name=\"serverUrl\" id=\"serverUrl\" />\n      </label>\n\n      <label>Check for new jobs every\n        <input name=\"pollSeconds\" id=\"pollSeconds\" type=\"number\" min=\"2\" max=\"60\" />\n      </label>\n\n      <label style=\"margin-top:14px; font-weight:600; display:flex; gap:9px; align-items:center;\">\n        <input type=\"checkbox\" name=\"duplex\" id=\"duplex\" style=\"width:auto; margin:0;\" />\n        Print on both sides when the printer supports it\n      </label>\n\n      <div class=\"row\">\n        <button class=\"primary\" type=\"submit\" id=\"save\">Save and start</button>\n        <button class=\"ghost\" type=\"button\" id=\"check\">Kya galat hai? Check kijiye</button>\n        <button class=\"ghost\" type=\"button\" id=\"test\">Print a test page</button>\n      </div>\n    </form>\n  </div>\n\n  <div class=\"card\">\n    <h2>What has happened</h2>\n    <div class=\"log\" id=\"log\"></div>\n  </div>\n</div>\n\n<script>\n  const $ = (id) => document.getElementById(id);\n  let loadedOnce = false;\n\n  function paint(state) {\n    const conn = $(\"conn\");\n    conn.className = \"pill \" + (state.running && state.connected ? \"on\" : \"off\");\n    $(\"conn-text\").textContent = state.stoppedReason\n      ? \"Stopped\"\n      : state.running\n        ? (state.connected ? \"Connected\" : \"Trying to reach the website…\")\n        : \"Not started\";\n\n    if (state.stationName) {\n      $(\"station-pill\").hidden = false;\n      $(\"station-pill\").textContent = state.stationName;\n    }\n\n    if (state.version) $(\"version\").textContent = \"\\u00b7 v\" + state.version;\n    $(\"update-box\").hidden = !state.updateAvailable;\n    if (state.latestVersion) $(\"update-version\").textContent = \"v\" + state.latestVersion;\n    $(\"s-queued\").textContent = state.queued ?? 0;\n    $(\"s-printed\").textContent = state.printed ?? 0;\n    $(\"s-failed\").textContent = state.failed ?? 0;\n\n    const problem = state.stoppedReason || state.lastError || (state.problems || [])[0] || \"\";\n    $(\"problem\").hidden = !problem;\n    $(\"problem\").textContent = problem;\n\n    if (!loadedOnce) {\n      $(\"agentToken\").value = state.config.agentToken || \"\";\n      $(\"serverUrl\").value = state.config.serverUrl || \"\";\n      $(\"pollSeconds\").value = state.config.pollSeconds || 5;\n      $(\"duplex\").checked = !!state.config.duplex;\n\n      const select = $(\"printerName\");\n      select.innerHTML = \"\";\n      const names = state.printers && state.printers.length ? state.printers : [];\n      if (!names.length) {\n        select.appendChild(new Option(\"No printer found on this computer\", \"\"));\n      }\n      for (const name of names) {\n        const option = new Option(name, name);\n        if (name === state.config.printerName) option.selected = true;\n        select.appendChild(option);\n      }\n      loadedOnce = true;\n    }\n\n    $(\"log\").innerHTML = (state.log || [])\n      .map((line) => '<div class=\"' + line.level + '\">' +\n        new Date(line.at).toLocaleTimeString() + \" &nbsp; \" +\n        line.message.replace(/[<>&]/g, (c) => ({ \"<\": \"&lt;\", \">\": \"&gt;\", \"&\": \"&amp;\" }[c])) + \"</div>\")\n      .join(\"\");\n  }\n\n  $(\"update-btn\").addEventListener(\"click\", async () => {\n    $(\"update-btn\").disabled = true;\n    $(\"update-btn\").textContent = \"Install ho raha hai...\";\n    try {\n      await fetch(\"/api/update\", { method: \"POST\", headers: { \"Content-Type\": \"application/json\" }, body: \"{}\" });\n    } catch {}\n    setTimeout(() => location.reload(), 8000);\n  });\n\n  async function refresh() {\n    try { paint(await (await fetch(\"/api/state\")).json()); } catch {}\n  }\n\n  $(\"form\").addEventListener(\"submit\", async (event) => {\n    event.preventDefault();\n    $(\"save\").disabled = true;\n    const body = {\n      agentToken: $(\"agentToken\").value,\n      printerName: $(\"printerName\").value,\n      serverUrl: $(\"serverUrl\").value,\n      pollSeconds: Number($(\"pollSeconds\").value),\n      duplex: $(\"duplex\").checked,\n    };\n    try {\n      const response = await fetch(\"/api/save\", {\n        method: \"POST\", headers: { \"Content-Type\": \"application/json\" }, body: JSON.stringify(body),\n      });\n      const json = await response.json();\n      if (json.problems && json.problems.length) alert(json.problems.join(\"\\\\n\"));\n    } finally {\n      $(\"save\").disabled = false;\n      refresh();\n    }\n  });\n\n  $(\"check\").addEventListener(\"click\", async () => {\n    $(\"check\").disabled = true;\n    $(\"check\").textContent = \"Check kar rahe hain…\";\n    try {\n      const json = await (await fetch(\"/api/check\", { method: \"POST\", headers: { \"Content-Type\": \"application/json\" }, body: \"{}\" })).json();\n      const box = $(\"findings\");\n      box.hidden = false;\n      const label = { ok: \"Theek\", error: \"Gadbad\", warn: \"Dhyan\", fix: \"Ye kariye\", info: \"\" };\n      box.innerHTML = (json.findings || [])\n        .map((f) => '<div class=\"finding ' + f.level + '\"><span class=\"tag\">' +\n          (label[f.level] || \"\") + '</span><span>' +\n          f.text.replace(/[<>&]/g, (c) => ({ \"<\": \"&lt;\", \">\": \"&gt;\", \"&\": \"&amp;\" }[c])) + \"</span></div>\")\n        .join(\"\");\n    } catch {\n      alert(\"Check nahi ho paya. Kya ye program abhi bhi chal raha hai?\");\n    } finally {\n      $(\"check\").disabled = false;\n      $(\"check\").textContent = \"Kya galat hai? Check kijiye\";\n      refresh();\n    }\n  });\n\n  $(\"test\").addEventListener(\"click\", async () => {\n    $(\"test\").disabled = true;\n    try {\n      const json = await (await fetch(\"/api/test-print\", { method: \"POST\", headers: { \"Content-Type\": \"application/json\" }, body: \"{}\" })).json();\n      alert(json.ok ? \"Sent to \" + json.printer + \". Check the tray.\" : (json.error || \"Could not print.\"));\n    } finally {\n      $(\"test\").disabled = false;\n      refresh();\n    }\n  });\n\n  refresh();\n  setInterval(refresh, 2000);\n</script>\n</body>\n</html>`;\n}\n",
  "lib/log.mjs": "/**\n * What the shop owner sees when something goes wrong.\n *\n * Kept in memory and capped: this program runs for months on a counter PC\n * that nobody restarts, and an unbounded log is a memory leak with a\n * respectable name. Nothing here is written to disk — a customer's file name\n * passes through these lines, and the promise is that nothing of theirs stays\n * on this computer.\n */\n\nconst MAX_LINES = 200;\n\nexport function createLog() {\n  const lines = [];\n\n  function push(level, message) {\n    lines.unshift({ at: new Date().toISOString(), level, message: String(message).slice(0, 500) });\n    if (lines.length > MAX_LINES) lines.length = MAX_LINES;\n\n    const stamp = new Date().toLocaleTimeString();\n    const prefix = { error: \"!\", warn: \"*\", success: \"+\", info: \" \" }[level] ?? \" \";\n    console.log(`${stamp} ${prefix} ${message}`);\n  }\n\n  return { push, lines: () => lines.slice(0, 60) };\n}\n",
  "lib/version.mjs": "/**\n * Which build of the Print Station this is.\n *\n * Printed on startup and shown on the settings page for one reason: a shop\n * owner sent screenshot after screenshot of a failure that had already been\n * fixed, because nothing on screen said which version was running and the\n * Downloads folder held four copies with identical names. The version answers\n * that in the first line of the log.\n *\n * Bump it whenever the program's behaviour changes.\n */\nexport const PRINT_STATION_VERSION = \"2.2.0\";\n",
  "lib/ensure-node.ps1": "<#\n  Get Node onto this computer without asking the shop to.\n\n  The program is written for Node, and the old answer to a counter PC that\n  did not have it was a link to nodejs.org. That is where installs died: the\n  installer is an MSI that wants administrator rights the shop assistant does\n  not have, the page offers half a dozen buttons, and somebody has to decide\n  which one. A shop owner should not have to know what Node is at all.\n\n  So this fetches it: the official Windows ZIP from nodejs.org, which is one\n  self-contained node.exe -- no installer, no admin rights, nothing added to\n  PATH, nothing else on the machine touched. It lands in the program's own\n  AppData folder and is reused forever after, including by every later\n  download of the Print Station.\n\n  What is already there wins: a Node installed the normal way is used as-is.\n\n  Writes the chosen node.exe into <AppData>\\node-path.txt. The launchers read\n  that file rather than parsing this script's output, so progress messages\n  can never be mistaken for the answer.\n#>\n$ErrorActionPreference = \"Stop\"\n$ProgressPreference = \"SilentlyContinue\"\n\n# Windows PowerShell 5.1 still defaults to TLS 1.0 on older builds, and\n# nodejs.org refuses that.\ntry { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch {}\n\n$appData  = Join-Path $env:LOCALAPPDATA \"DigiConnectPrintStation\"\n$nodeDir  = Join-Path $appData \"node\"\n$nodeExe  = Join-Path $nodeDir \"node.exe\"\n$pathFile = Join-Path $appData \"node-path.txt\"\n\nfunction Save-NodePath($exe) {\n  New-Item -ItemType Directory -Force -Path $appData | Out-Null\n  Set-Content -Path $pathFile -Value $exe -Encoding ASCII\n}\n\n# 1. Installed the normal way? Use it and change nothing.\n$installed = Get-Command node.exe -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1\nif ($installed) {\n  Save-NodePath $installed.Source\n  exit 0\n}\n\n# 2. Fetched here on an earlier run?\nif (Test-Path $nodeExe) {\n  Save-NodePath $nodeExe\n  exit 0\n}\n\nWrite-Host \"\"\nWrite-Host \"  Node.js is computer par nahi hai. Khud download kar raha hoon.\" -ForegroundColor Cyan\nWrite-Host \"  (~35 MB, sirf ek baar. Na installer, na admin password.)\"\nWrite-Host \"\"\n\n$arch =\n  if ($env:PROCESSOR_ARCHITECTURE -eq \"ARM64\" -or $env:PROCESSOR_ARCHITEW6432 -eq \"ARM64\") { \"arm64\" }\n  elseif ([Environment]::Is64BitOperatingSystem) { \"x64\" }\n  else { \"x86\" }\n\n$temp = Join-Path $env:TEMP (\"dcps-node-\" + [guid]::NewGuid().ToString(\"N\"))\nNew-Item -ItemType Directory -Force -Path $temp | Out-Null\n\ntry {\n  # The version is asked for, never guessed. A hardcoded number goes stale and\n  # then 404s on a counter PC, which is the worst place to find out.\n  $index = Invoke-RestMethod -Uri \"https://nodejs.org/dist/index.json\" -UseBasicParsing\n  $release = $index | Where-Object { $_.lts -and $_.files -contains \"win-$arch-zip\" } | Select-Object -First 1\n  if (-not $release) { throw \"nodejs.org has no LTS build for win-$arch.\" }\n\n  $name = \"node-$($release.version)-win-$arch\"\n  $zip  = Join-Path $temp \"$name.zip\"\n\n  Write-Host \"  ... $($release.version) ($arch)\"\n  Invoke-WebRequest -Uri \"https://nodejs.org/dist/$($release.version)/$name.zip\" -OutFile $zip -UseBasicParsing\n\n  <#\n    Check what came down before running it.\n\n    This is a program binary arriving over a shop's network, often through\n    somebody else's wifi and whatever box is between. The published checksum\n    costs one small request and turns a silent corruption -- or a swapped\n    file -- into a clear refusal.\n  #>\n  Write-Host \"  ... checking the download\"\n  $sums = (Invoke-WebRequest -Uri \"https://nodejs.org/dist/$($release.version)/SHASUMS256.txt\" -UseBasicParsing).Content\n  $line = ($sums -split \"`n\" | Where-Object { $_ -match [regex]::Escape(\"$name.zip\") } | Select-Object -First 1)\n  if (-not $line) { throw \"nodejs.org did not publish a checksum for $name.zip.\" }\n  $expected = ($line -split '\\s+')[0].Trim().ToLower()\n  $actual = (Get-FileHash -Path $zip -Algorithm SHA256).Hash.ToLower()\n  if ($expected -ne $actual) { throw \"The downloaded Node.js does not match its published checksum.\" }\n\n  Expand-Archive -Path $zip -DestinationPath $temp -Force\n  $found = Join-Path $temp \"$name\\node.exe\"\n  if (-not (Test-Path $found)) { throw \"node.exe was not inside the download.\" }\n\n  New-Item -ItemType Directory -Force -Path $nodeDir | Out-Null\n  Copy-Item -Path $found -Destination $nodeExe -Force\n\n  Save-NodePath $nodeExe\n  Write-Host \"\"\n  Write-Host \"  Node.js taiyar hai. Ab kuch install nahi karna.\" -ForegroundColor Green\n  Write-Host \"\"\n  exit 0\n} catch {\n  Write-Host \"\"\n  Write-Host \"  Node.js download nahi ho paya.\" -ForegroundColor Yellow\n  Write-Host \"  $($_.Exception.Message)\"\n  Write-Host \"\"\n  Write-Host \"  Aksar iski wajah dukaan ka internet ya firewall hota hai.\"\n  Write-Host \"  Ek baar https://nodejs.org/en/download browser me kholkar dekhiye -\"\n  Write-Host \"  na khule to network hi rok raha hai.\"\n  Write-Host \"\"\n  exit 1\n} finally {\n  Remove-Item -Path $temp -Recurse -Force -ErrorAction SilentlyContinue\n}\n",
  "lib/background.ps1": "<#\n  Printing that survives the window being closed.\n\n  The counter PC's black window was doing two jobs: running the program, and\n  reminding the shop it was running. It did the second badly and the first\n  fatally -- one accidental X, or one \"clean up the desktop\" at closing time,\n  and the next customer paid for pages that never came out. Nobody at a busy\n  shop should have to guard a console window.\n\n  So the program is started with no window, and again every time the computer\n  is switched on. Nothing here needs administrator rights: it writes one\n  shortcut into the user's own Startup folder, which is why it works on a\n  shared shop machine whose owner is not an admin.\n\n      powershell -ExecutionPolicy Bypass -File lib\\background.ps1\n      powershell -ExecutionPolicy Bypass -File lib\\background.ps1 -Remove\n#>\nparam([switch]$Remove)\n\n$ErrorActionPreference = \"Stop\"\n\n$source  = Split-Path -Parent $PSScriptRoot\n# Where the program lives for good. A shop runs this from Downloads, and\n# Downloads gets cleaned: a startup shortcut pointing there stopped printing\n# the day somebody tidied up. So the program is copied here once, and the\n# shortcut points here. Every later download is copied over the same place.\n$folder  = Join-Path $env:LOCALAPPDATA \"DigiConnectPrintStation\\app\"\n$startup = [Environment]::GetFolderPath(\"Startup\")\n$link    = Join-Path $startup \"DigiConnect Print Station.lnk\"\n$vbs     = Join-Path $folder \"lib\\run-hidden.vbs\"\n$ps1     = Join-Path $folder \"lib\\run-hidden.ps1\"\n$wscript = Join-Path $env:WINDIR \"System32\\wscript.exe\"\n$port    = if ($env:DCPS_PORT) { $env:DCPS_PORT } else { \"7171\" }\n\n<#\n  Stop whichever copy is already running.\n\n  Matched on the command line rather than on \"node.exe\" alone, because a\n  counter PC may be running somebody else's Node program and killing that\n  would be a worse bug than the one being fixed here.\n#>\nfunction Stop-Station {\n  # The keepalive first: stopped after its child, it would start a new one.\n  Get-CimInstance Win32_Process -Filter \"Name = 'node.exe'\" -ErrorAction SilentlyContinue |\n    Where-Object { $_.CommandLine -and $_.CommandLine -like \"*station.mjs*\" } |\n    Sort-Object { if ($_.CommandLine -like \"*keepalive*\") { 0 } else { 1 } } |\n    ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }\n}\n\nfunction Test-Station {\n  foreach ($attempt in 1..12) {\n    Start-Sleep -Seconds 1\n    try {\n      return Invoke-RestMethod -Uri \"http://localhost:$port/api/state\" -TimeoutSec 2\n    } catch {\n      # Not up yet. Node takes a moment, and listing printers takes longer.\n    }\n  }\n  return $null\n}\n\nif (-not (Test-Path (Join-Path $source \"station.mjs\"))) {\n  Write-Host \"\"\n  Write-Host \"  station.mjs nahi mili. Poori zip Extract kijiye aur folder ke\" -ForegroundColor Yellow\n  Write-Host \"  ANDAR se ye file chalaiye.\" -ForegroundColor Yellow\n  Write-Host \"\"\n  exit 1\n}\n\nif ($Remove) {\n  if (Test-Path $link) { Remove-Item $link -Force }\n  Stop-Station\n  Write-Host \"\"\n  Write-Host \"  Background printing band kar di.\" -ForegroundColor Yellow\n  Write-Host \"  Ab print tabhi hoga jab aap khud 'Start Print Station' chalayenge.\"\n  Write-Host \"\"\n  exit 0\n}\n\n# Fetches Node if this computer does not have it, and records which node.exe\n# the hidden runners should use. Nothing for the shop to install by hand.\n& (Join-Path $PSScriptRoot \"ensure-node.ps1\")\n\n# Install (or update) the permanent copy. Skipped when this already is it.\nStop-Station\nif ((Resolve-Path $source).Path.TrimEnd('\\') -ne $folder.TrimEnd('\\')) {\n  New-Item -ItemType Directory -Force -Path $folder | Out-Null\n  Copy-Item -Path (Join-Path $source \"*\") -Destination $folder -Recurse -Force\n  Write-Host \"  Program yahan install ho gaya: $folder\"\n  Write-Host \"  (Downloads wala folder ab delete bhi kar sakte hain.)\"\n}\n$nodePathFile = Join-Path $env:LOCALAPPDATA \"DigiConnectPrintStation\\node-path.txt\"\nif (-not (Test-Path $nodePathFile)) {\n  Write-Host \"\"\n  Write-Host \"  Node.js taiyar nahi ho paya, isliye background me nahi daal saka.\" -ForegroundColor Yellow\n  Write-Host \"  Uparwala message padhiye - usme wajah likhi hai.\"\n  Write-Host \"\"\n  exit 1\n}\n\n$useVbs = Test-Path $wscript\n\n$shell = New-Object -ComObject WScript.Shell\n$shortcut = $shell.CreateShortcut($link)\nif ($useVbs) {\n  $shortcut.TargetPath = $wscript\n  $shortcut.Arguments  = \"`\"$vbs`\"\"\n} else {\n  $shortcut.TargetPath = \"powershell.exe\"\n  $shortcut.Arguments  = \"-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `\"$ps1`\"\"\n}\n$shortcut.WorkingDirectory = $folder\n$shortcut.Description = \"Prints what your customers order at your QR counter\"\n$shortcut.Save()\n\n# Start it now, so the shop does not have to restart the computer to see this\n# work. Any copy started from the black window is stopped first, or the new\n# one would find the port taken and quit straight away.\nStop-Station\nStart-Sleep -Seconds 1\nif ($useVbs) {\n  Start-Process -FilePath $wscript -ArgumentList \"`\"$vbs`\"\" -WindowStyle Hidden\n} else {\n  Start-Process -FilePath \"powershell.exe\" -ArgumentList \"-NoProfile\",\"-ExecutionPolicy\",\"Bypass\",\"-WindowStyle\",\"Hidden\",\"-File\",\"`\"$ps1`\"\" -WindowStyle Hidden\n}\n\n$state = Test-Station\n\nWrite-Host \"\"\nif ($state) {\n  Write-Host \"  Ho gaya. Print Station ab background me chal raha hai.\" -ForegroundColor Green\n  Write-Host \"\"\n  Write-Host \"  * Koi window khuli rakhne ki zaroorat nahi.\"\n  Write-Host \"  * Computer on hote hi khud chalu ho jayega.\"\n  if ($state.config -and $state.config.printerName) {\n    Write-Host \"  * Printer: $($state.config.printerName)\"\n  }\n  Write-Host \"  * Haal dekhna ho to: http://localhost:$port\"\n  Write-Host \"  * Band karna ho to 'Background band kijiye' par double-click.\"\n  Write-Host \"\"\n  # The startup shortcut points at this folder. A newer download lands in a\n  # new folder with a new key, and the old hidden copy would keep starting\n  # with the retired one -- silently, now that there is no window to see it.\n  Write-Host \"  * Program band ho jaye to khud dobara chalu ho jata hai.\"\n  Write-Host \"  * Printer badalna ho to partner panel se badaliye.\"\n} else {\n  Write-Host \"  Startup me daal diya, lekin chalu hua ya nahi ye pakka nahi.\" -ForegroundColor Yellow\n  Write-Host \"\"\n  Write-Host \"  http://localhost:$port kholkar dekhiye. Page na khule to ek baar\"\n  Write-Host \"  'Start Print Station' se chalaiye - wahan galti likhi hui milegi.\"\n}\nWrite-Host \"\"\n",
  "lib/run-hidden.vbs": "' Starts the Print Station with no window at all.\n'\n' The shop asked the obvious question: why must a black window stay open on\n' the counter PC all day? It must not. This is the same program, started\n' with the window hidden, so closing nothing stops printing.\n'\n' It works out its own folder rather than being told one, so the shop can\n' move or rename the folder and this keeps working.\nOption Explicit\n\nDim fso, shell, folder, pathFile, node, stream\nSet fso = CreateObject(\"Scripting.FileSystemObject\")\nSet shell = CreateObject(\"WScript.Shell\")\n\nfolder = fso.GetParentFolderName(fso.GetParentFolderName(WScript.ScriptFullName))\n\nIf Not fso.FileExists(folder & \"\\lib\\keepalive-station.mjs\") Then\n  WScript.Quit 1\nEnd If\n\n' Which node.exe: the one ensure-node.ps1 settled on. It may be a copy this\n' program fetched itself, which is not on PATH and never will be.\nnode = \"node\"\npathFile = shell.ExpandEnvironmentStrings(\"%LOCALAPPDATA%\") & \"\\DigiConnectPrintStation\\node-path.txt\"\nIf fso.FileExists(pathFile) Then\n  Set stream = fso.OpenTextFile(pathFile, 1)\n  If Not stream.AtEndOfStream Then node = Trim(stream.ReadLine)\n  stream.Close\nEnd If\n\nshell.CurrentDirectory = folder\n' Started through the keepalive, which restarts station.mjs if it ever\n' crashes -- otherwise a crash at noon meant no printing until next boot.\n' 0 = no window, False = do not wait for it to finish.\nshell.Run \"\"\"\" & node & \"\"\" \"\"\" & folder & \"\\lib\\keepalive-station.mjs\"\"\", 0, False\n",
  "lib/run-hidden.ps1": "<#\n  The same hidden start, for a Windows without VBScript.\n\n  VBScript is on its way out of Windows, and a shop that has already removed\n  it would otherwise get a startup entry that silently does nothing. This is\n  the fallback the shortcut points at in that case.\n#>\n$ErrorActionPreference = \"Stop\"\n\n$folder = Split-Path -Parent $PSScriptRoot\n# The keepalive restarts station.mjs if it ever crashes.\n$station = Join-Path $folder \"lib\\keepalive-station.mjs\"\nif (-not (Test-Path $station)) { exit 1 }\n\n# Whatever ensure-node.ps1 settled on -- often a node.exe this program\n# fetched itself, which is not on PATH.\n$pathFile = Join-Path $env:LOCALAPPDATA \"DigiConnectPrintStation\\node-path.txt\"\n$node = if (Test-Path $pathFile) { (Get-Content -Path $pathFile -TotalCount 1).Trim() } else { \"node\" }\nif (-not $node) { $node = \"node\" }\n\nStart-Process -FilePath $node -ArgumentList \"`\"$station`\"\" -WorkingDirectory $folder -WindowStyle Hidden\n",
  "lib/keepalive-station.mjs": "#!/usr/bin/env node\n/**\n * Keeps the Print Station running.\n *\n * Background mode started the program with no window and again at every boot,\n * but if it crashed in the afternoon it stayed down until the next morning —\n * and with no window there was nothing on the screen to say so. Customers\n * paid, and nothing printed.\n *\n * This is the program the hidden launchers start. It runs station.mjs as a\n * child and starts it again whenever it stops, waiting a little longer each\n * time it falls over quickly so a broken install does not spin the CPU.\n *\n * A clean exit (code 0) is respected: that is either somebody stopping it on\n * purpose, or another copy already holding the port — in both cases starting\n * it again would be wrong.\n *\n * No dependencies, like the rest of the program.\n */\nimport { spawn } from \"node:child_process\";\nimport { dirname, join, resolve } from \"node:path\";\nimport { fileURLToPath } from \"node:url\";\n\nconst station = join(dirname(fileURLToPath(import.meta.url)), \"..\", \"station.mjs\");\n\n/** Seconds to wait before restart number `failures` (1-based). */\nexport function restartDelaySeconds(failures) {\n  return Math.min(60, 2 ** Math.max(0, failures - 1) * 2);\n}\n\nlet child = null;\nlet stopping = false;\nlet failures = 0;\n\nfunction start() {\n  const startedAt = Date.now();\n  child = spawn(process.execPath, [station], {\n    cwd: dirname(station),\n    stdio: \"ignore\",\n    windowsHide: true,\n  });\n\n  child.on(\"exit\", (code) => {\n    child = null;\n    if (stopping || code === 0) process.exit(0);\n\n    // 75: the program updated itself and wants to be started again, now.\n    if (code === 75) {\n      failures = 0;\n      setTimeout(start, 1000);\n      return;\n    }\n\n    // A run that lasted a minute was a crash, not a broken install: start\n    // over from the shortest wait.\n    failures = Date.now() - startedAt > 60_000 ? 1 : failures + 1;\n    setTimeout(start, restartDelaySeconds(failures) * 1000);\n  });\n\n  child.on(\"error\", () => {\n    // spawn itself failed (node.exe moved?). Treated as a crash.\n  });\n}\n\nfor (const signal of [\"SIGINT\", \"SIGTERM\"]) {\n  process.on(signal, () => {\n    stopping = true;\n    if (child) child.kill(signal);\n    else process.exit(0);\n  });\n}\n\n// Run only when started as a program, not when a test imports the helper.\n// Compared case-insensitively: Windows hands the path over in whatever case\n// the shortcut was written with.\nconst self = resolve(fileURLToPath(import.meta.url)).toLowerCase();\nif (process.argv[1] && resolve(process.argv[1]).toLowerCase() === self) start();\n",
  "lib/local-guard.mjs": "/**\n * Who may talk to the settings page on localhost:7171.\n *\n * Listening on 127.0.0.1 keeps the shop's network out, but not the shop's own\n * browser: any website the counter PC opens can fire requests at localhost.\n * Two ways that went wrong:\n *\n *  - A \"simple\" cross-site POST (text/plain, no preflight) reached /api/save,\n *    which read the body as JSON whatever its type — so a web page could\n *    point serverUrl at itself, and the program would then send this shop's\n *    key to it on the next poll.\n *  - DNS rebinding: a site re-pointing its own hostname at 127.0.0.1 can read\n *    responses, including /api/state, which carried the key.\n *\n * So: the Host must be localhost or 127.0.0.1 on our port (kills rebinding),\n * and any request that changes something must be JSON from our own origin\n * (kills cross-site POSTs — a JSON POST from elsewhere needs a preflight this\n * server never grants).\n */\nexport function isAllowedHost(host, port) {\n  const value = String(host ?? \"\").toLowerCase();\n  return value === `localhost:${port}` || value === `127.0.0.1:${port}`;\n}\n\nexport function isAllowedWrite({ method, origin, contentType, port }) {\n  if (method === \"GET\" || method === \"HEAD\") return true;\n  if (!/^application\\/json\\b/i.test(String(contentType ?? \"\"))) return false;\n  if (origin === undefined || origin === null || origin === \"\") return false;\n  return origin === `http://localhost:${port}` || origin === `http://127.0.0.1:${port}`;\n}\n\n/** What a saved token field means: blank or the masked display keeps the current key. */\nexport function tokenFromForm(submitted, current) {\n  const value = String(submitted ?? \"\").trim();\n  if (!value || value.includes(\"…\")) return current;\n  return value;\n}\n",
  "lib/secure-key.mjs": "import { createHash, randomBytes } from \"node:crypto\";\n\n/**\n * Retire the key that came inside the download zip.\n *\n * The zip carries the station's key in plain text and outlives the install —\n * it sits in Downloads, gets emailed, goes onto a pen drive. Anybody holding\n * it could pull this shop's customers' documents. So the first time the\n * program runs on a key it took from a zip, it makes a fresh key of its own,\n * tells the server only the new key's hash, and switches to it. The zip's key\n * is dead from then on, and the real key exists only in this computer's\n * profile.\n *\n * Safe against a lost reply: the new key is saved (as pendingToken) before\n * the server is asked, and if the answer never arrives the next attempt\n * first checks whether the server already took it.\n */\nexport function newKey() {\n  return `dcp_${randomBytes(24).toString(\"base64url\")}`;\n}\n\nexport function keyHash(key) {\n  return createHash(\"sha256\").update(key).digest(\"hex\");\n}\n\nexport async function secureBundledKey({ config, save, makeApi, log = () => {}, generate = newKey }) {\n  // A previous attempt may have succeeded without our hearing the answer.\n  if (config.pendingToken) {\n    try {\n      await makeApi(config.pendingToken).whoami();\n      log(\"success\", \"Download wali key badal di gayi - ab key sirf is computer me hai.\");\n      return save({ ...config, agentToken: config.pendingToken, pendingToken: \"\" });\n    } catch (error) {\n      if (error?.status !== 401) throw error;\n    }\n  }\n\n  // Only a key that came from a zip needs retiring.\n  if (!config.agentToken || config.agentToken !== config.seededFrom) {\n    return config.pendingToken ? save({ ...config, pendingToken: \"\" }) : config;\n  }\n\n  const fresh = config.pendingToken || generate();\n  let current = save({ ...config, pendingToken: fresh });\n\n  try {\n    await makeApi(current.agentToken).rotateKey(keyHash(fresh));\n  } catch (error) {\n    if (error?.status !== 409) throw error;\n    // \"Already changed\": by us (reply lost) if the fresh key works.\n    try {\n      await makeApi(fresh).whoami();\n    } catch {\n      return current;\n    }\n  }\n\n  current = save({ ...current, agentToken: fresh, pendingToken: \"\" });\n  log(\"success\", \"Download wali key badal di gayi - ab key sirf is computer me hai.\");\n  return current;\n}\n",
  "lib/self-update.mjs": "import { mkdirSync, renameSync, writeFileSync } from \"node:fs\";\nimport { dirname, isAbsolute, join, normalize, sep } from \"node:path\";\n\n/**\n * Update the connector in place, from the website.\n *\n * The partner presses \"Update install karo\" in their panel; on its next poll\n * the connector downloads the current program files (with its own key — the\n * key itself is never part of the download, so updating never logs a shop\n * out), writes them over its own folder, and exits with RESTART_CODE so the\n * keepalive starts the new version a couple of seconds later.\n *\n * Each file is written beside its target and renamed into place, so a power\n * cut mid-update leaves every file either old or new, never half-written.\n * Only plain relative paths inside the program folder are accepted.\n */\nexport const RESTART_CODE = 75;\n\nconst NEVER_OVERWRITE = new Set([\"config.json\"]);\n\nexport function isSafeRelativePath(path) {\n  const value = String(path ?? \"\");\n  if (!value || isAbsolute(value) || value.includes(\"\\0\")) return false;\n  if (!/^[A-Za-z0-9 _.\\-/]+$/.test(value)) return false;\n  const clean = normalize(value);\n  return !clean.split(sep).includes(\"..\") && !clean.split(\"/\").includes(\"..\");\n}\n\nexport function applyUpdate({ files, folder, write = writeFileSync, rename = renameSync, mkdir = mkdirSync }) {\n  const entries = Object.entries(files ?? {});\n  if (!entries.length) throw new Error(\"The update had no files.\");\n\n  for (const [path] of entries) {\n    if (!isSafeRelativePath(path)) throw new Error(`Refusing an unsafe path in the update: ${path}`);\n  }\n\n  let written = 0;\n  for (const [path, content] of entries) {\n    if (NEVER_OVERWRITE.has(path) || typeof content !== \"string\") continue;\n    const target = join(folder, path);\n    mkdir(dirname(target), { recursive: true });\n    write(`${target}.new`, content, \"utf8\");\n    rename(`${target}.new`, target);\n    written += 1;\n  }\n  return written;\n}\n\n/** \"2.10.0\" > \"2.9.3\". Unparseable parts count as 0. */\nexport function isNewer(latest, current) {\n  const parts = (value) => String(value ?? \"0.0.0\").split(\".\").map((part) => Number.parseInt(part, 10) || 0);\n  const a = parts(latest);\n  const b = parts(current);\n  for (let index = 0; index < 3; index += 1) {\n    if ((a[index] ?? 0) !== (b[index] ?? 0)) return (a[index] ?? 0) > (b[index] ?? 0);\n  }\n  return false;\n}\n",
};
